/* ================= メイン ================= */
function nextAud() { return AUDS.find(a => a.d >= G.day); }
const inCamp = () => G.day >= CAMP[0] && G.day <= CAMP[1];
function statMult(key) { const t = TYPES[G.type]; return (t.boost && t.boost[key]) || 1; }
function skillFx() {
  const f = { g: {}, all: 0, aud: 0, fan: 0, st: 0, shield: 0, iron: 0 };
  if (!G || !G.skills) return f;
  G.skills.forEach(id => {
    const s = SKILLS.find(x => x.id === id); if (!s) return;
    if (s.fx.g) for (const k in s.fx.g) f.g[k] = (f.g[k] || 0) + s.fx.g[k];
    ["all", "aud", "fan", "st", "shield", "iron"].forEach(k => { if (s.fx[k]) f[k] += s.fx[k]; });
  });
  return f;
}
function renderMain() {
  if (!G) return renderTitle();
  const a = nextAud();
  $("mDay").textContent = G.day;
  $("mPhase").textContent = PHASE(G.day);
  const songTag = inCamp() && G.song ? `<div class="camp">合宿中　課題曲『${SONGS.find(x => x.id === G.song).n}』</div>` : (inCamp() ? `<div class="camp">強化合宿中</div>` : "");
  const rankTag = G.lastRank ? `<div style="font-size:9.5px;color:var(--ink3);margin-top:2px">前回審査 <b style="color:var(--gold)">${G.lastRank}位</b>/${G.lastRankOf || "?"}人</div>` : "";
  $("mNext").innerHTML = a
    ? (a.d === G.day ? `<b>本日 ${a.n}</b>` : `${a.n}まで <b>あと${a.d - G.day}日</b>`) + songTag + rankTag
    : "";
  $("mName").textContent = G.name;
  const avg = STATS.reduce((s, x) => s + G.st[x.k], 0) / 5;
  $("mTitleTag").textContent = avg >= 85 ? "優勝候補" : avg >= 70 ? "上位常連" : avg >= 55 ? "注目の候補生" : avg >= 35 ? "候補生" : "研修生";
  $("mAv").src = AVATARS[G.av].img;
  $("mOutfit").textContent = G.outfit ? OUTFITS.find(o => o.id === G.outfit).e : "";
  $("mStam").style.width = clamp(G.stam / G.maxStam * 100, 0, 100) + "%";
  $("mStam").style.background = G.stam < 25 ? "#e63946" : G.stam < 55 ? "#ffcf5c" : "#3ddc97";
  $("mStamN").textContent = Math.round(G.stam);
  const cd = CONDS[G.cond];
  $("mCond").textContent = cd.n; $("mCond").style.background = cd.c;
  $("mFans").textContent = G.fans.toLocaleString();
  $("mWarn").classList.toggle("hide", !G.warn);

  $("mStats").innerHTML = STATS.map(s => {
    const v = Math.round(G.st[s.k]), rk = rank(v);
    return `<div class="strow"><span class="sn">${s.n}</span>
      <span class="rk" style="background:${rk[2]}">${rk[1]}</span>
      <div class="gauge"><u style="width:${v}%;background:${s.c}"></u></div>
      <span class="sv">${v}</span></div>`;
  }).join("");

  if (a && a.d === G.day) {
    $("mCmds").innerHTML = `<button class="cmd aud wide" data-c="aud">
      <span class="ce">🎬</span><span><b>${a.n} へ</b><small>${a.sub}</small></span></button>`;
  } else {
    const fx = skillFx(), extra = inCamp() ? 4 : 0;
    const lv = lessonLv();
    $("mCmds").innerHTML = CMDS.map(c => {
      const cost = Math.max(6, c.st + fx.st + extra);
      const low = G.stam < cost;
      return `<button class="cmd" data-c="${c.id}">
        <span class="ce">${c.e}</span><span><b>${c.n}</b><small>${c.s}　<span style="color:var(--gold)">Lv.${lv}</span></small>
        <span class="cost" style="${low ? "color:#e63946" : ""}">体力 −${cost}</span></span></button>`;
    }).join("") +
      (inCamp() && G.team ? `<button class="cmd team wide" data-c="teamp"><span class="ce">🎬</span>
        <span><b>チーム練習${G.song ? `『${SONGS.find(x => x.id === G.song).n}』` : ""}</b><small>${G.team.map(i => CANDS[i].n).join("・")} と課題曲を合わせる${G.leader === "me" ? "（リーダー）" : ""}　体力 −34</small></span></button>` : "") +
      `<button class="cmd rest" data-c="rest"><span class="ce">😴</span><span><b>休養</b><small>体力を大きく回復</small></span></button>
       <button class="cmd talk" data-c="talk"><span class="ce">🤝</span><span><b>交流</b><small>候補生と話す</small></span></button>`;
  }
  $("mCmds").querySelectorAll(".cmd").forEach(b => b.onclick = () => doCmd(b.dataset.c));

  $("mChars").innerHTML = CAND_IDS.map(id => {
    const c = CANDS[id], v = clamp(G.aff[id], 0, 100), out = !G.alive.includes(id);
    const isTeam = G.team && G.team.includes(id);
    return `<div class="chip ${out ? "out" : ""}" data-c="${id}" style="${out ? "" : `box-shadow:0 0 0 1.5px ${c.c}66 inset`}">
      <img src="${c.img}" alt="${c.n}">
      <div class="cn">${isTeam ? "◆" : ""}${c.n}</div>
      ${out ? `<div class="outT">脱落</div>` : `<div class="hb"><u style="width:${v}%;background:${c.c}"></u></div>`}</div>`;
  }).join("");
  $("mChars").querySelectorAll(".chip").forEach(b => b.onclick = () => charInfo(b.dataset.c));

  show("scrMain");
  save();
}
$("mFoot").querySelectorAll(".fb").forEach(b => b.onclick = () => {
  sfx.tap();
  const a = b.dataset.a;
  if (a === "shop") openShop();
  else if (a === "zukan") openZukan();
  else if (a === "skill") openSkills();
  else { save(); renderTitle(); }
});

function charInfo(id) {
  const c = CANDS[id], v = Math.round(G.aff[id]);
  const nb = (BONDS[id] || []).find(b => v < b.at);
  const out = !G.alive.includes(id);
  openSheet(`<div class="ptitle">${c.n}<small>${c.full}　／　${c.role}</small></div>
    <div style="display:flex;gap:12px;align-items:center">${pImg(id, 96, 116)}
    <div style="flex:1">
      <div style="font-size:11px;color:var(--ink3);margin-bottom:5px">好感度 <b style="font-size:22px;color:${c.c}">${v}</b></div>
      <div class="gauge"><u style="width:${clamp(v, 0, 100)}%;background:${c.c}"></u></div>
      <div style="font-size:10.5px;color:var(--ink3);margin-top:8px;line-height:1.7">
        ${out ? "このオーディションからは去った。" : nb ? `つぎの特別イベントまで あと ${nb.at - v}` : "すべての特別イベントを見た"}</div>
    </div></div>
    <div style="height:14px"></div><button class="btn dark" onclick="closeSheet()">閉じる</button>`);
}

/* ================= コマンド ================= */
function doCmd(c) {
  sfx.tap();
  if (c === "aud") return startAudition();
  if (c === "rest") return doRest();
  if (c === "talk") return openTalkSelect();
  if (c === "teamp") return doTeamPractice();
  const cmd = CMDS.find(x => x.id === c);
  const fx = skillFx();
  const cost = Math.max(6, cmd.st + fx.st + (inCamp() ? 4 : 0));
  if (G.stam < cost) {
    if (!confirm("体力が足りない。無理をすると失敗しやすくなる。それでも練習する？")) return;
    G.over = true;
  } else G.over = false;
  G.stam = Math.max(0, G.stam - cost);
  G.golden = Math.random() < .25;
  if (G.golden) { toast("🌟 ゴールデンレッスン発生！ 今日の伸びが2倍！"); sfx.skill(); confetti(16); }
  startQuiz({
    mode: "lesson", genre: cmd.g, lv: lessonLv(), total: 8,
    title: `${G.golden ? "🌟 " : ""}${cmd.e} ${cmd.n}`,
    onEnd: r => finishLesson(cmd, r),
  });
}
function lessonLv() {
  const d = G.day;
  const base = d <= 4 ? 1 : d <= 10 ? 2 : d <= 17 ? 3 : d <= 24 ? 4 : 5;
  return clamp(base + lvAdjust(), 1, 5);
}
/* 実力連動：好調なら難しく、苦戦したらやさしく戻す（自信を折らないため下げは反応を速く） */
function lvAdjust() {
  const rec = (G && G.recentScores) || [];
  if (rec.length >= 2) {
    const last2 = rec.slice(-2).reduce((a, b) => a + b, 0) / 2;
    if (last2 < 38) return -2;          /* かなり苦戦 → 大きく戻す */
    if (last2 < 55) return -1;          /* 苦戦 → 1段やさしく */
  }
  if (rec.length >= 3) {
    const last3 = rec.slice(-3).reduce((a, b) => a + b, 0) / 3;
    if (last3 >= 93) return 2;          /* 余裕 → 一気に上げる */
    if (last3 >= 82) return 1;          /* 好調 → 1段むずかしく */
  }
  return 0;
}
function doRest() {
  const heal = ri(40, 60) + (G.cond >= 3 ? 10 : 0);
  G.stam = Math.min(G.maxStam, G.stam + heal);
  if (Math.random() < .45) G.cond = clamp(G.cond + 1, 0, 4);
  toast(`😴 休養した　体力 +${heal}`);
  maybeAdvice(() => endDay());
}
function doTeamPractice() {
  const cost = 34;
  if (G.stam < cost && !confirm("体力が足りない。それでもチーム練習する？")) return;
  G.stam = Math.max(0, G.stam - cost);
  const genre = pick(["frac", "ratio", "pi"]);
  const songN = G.song ? `『${SONGS.find(x => x.id === G.song).n}』` : "";
  startQuiz({
    mode: "lesson", genre, lv: lessonLv(), total: 10,
    title: `🎬 チーム練習${songN}`,
    onEnd: r => {
      const fx = skillFx();
      const mult = CONDS[G.cond].m * (1 + fx.all) * (G.leader === "me" ? 1.45 : 1.35);
      const base = 2.5 + r.score / 13;
      const gains = [];
      ["da", "ex"].forEach(k => { const d = addStat(k, gainFor(k, base * mult)); if (d) gains.push([STATS.find(s => s.k === k).n, d]); });
      const d3 = addStat("me", gainFor("me", base * mult * .5));
      if (d3) gains.push(["精神力", d3]);
      G.team.forEach(i => { G.aff[i] = clamp(G.aff[i] + 8, 0, 100); });
      G.totalQ += r.total; G.totalOK += r.correct;
      G.bestCombo = Math.max(G.bestCombo, r.best);
      if (r.score >= 95 && r.correct === r.total) { G.pf[genre]++; G.perfectLesson++; }
      showResult({
        title: "🎬 チーム練習", r, gains, fans: 0,
        extra: `<div class="smallnote">${G.team.map(i => CANDS[i].n).join("・")} の好感度 +8</div>`,
        after: () => checkSkills(() => endDay()),
      });
    },
  });
}

function openTalkSelect() {
  const alive = G.alive;
  openSheet(`<div class="ptitle">誰と話す？<small>好感度30／60／90で特別イベント</small></div>
   <div class="list">${alive.map(id => {
    const c = CANDS[id];
    return `<button class="item" data-c="${id}">${`<img class="ii" src="${c.img}" alt="">`}
      <div class="it"><b>${c.n}${G.team && G.team.includes(id) ? " ◆チーム" : ""}</b><small>${c.role}　好感度 ${Math.round(G.aff[id])}</small></div>
      <span style="font-size:15px;color:var(--ink3)">▶</span></button>`;
  }).join("")}</div>
   <div style="height:12px"></div><button class="btn dark" onclick="closeSheet()">やめる</button>`);
  $("sheetPanel").querySelectorAll(".item").forEach(b => b.onclick = () => { closeSheet(); doTalk(b.dataset.c); });
}
function doTalk(id) {
  const t = pick(TALKS[id]);
  G.stam = Math.min(G.maxStam, G.stam + 10);
  showEvent({
    c: id, t: t.t,
    ch: t.c.map(o => {
      const bonus = (G.team && G.team.includes(id)) ? 3 : 0;
      return { t: o.t, fx: { aff: { [id]: o.a + bonus }, silent: true }, after: () => { toast(`💬 ${CANDS[id].n}の好感度 +${o.a + bonus}`); endDay(); } };
    })
  });
}

/* ================= 練習結果 ================= */
function gainFor(key, base) {
  let g = base * statMult(key);
  const cur = G.st[key];
  if (cur >= 90) g *= .35; else if (cur >= 80) g *= .55; else if (cur >= 65) g *= .8;
  return g;
}
function addStat(key, v) {
  const before = Math.round(G.st[key]);
  G.st[key] = clamp(G.st[key] + v, 0, 100);
  return Math.round(G.st[key]) - before;
}
function finishLesson(cmd, r) {
  const fx = skillFx();
  let mult = CONDS[G.cond].m * (1 + (fx.g[cmd.g] || 0) + fx.all) * (1 + DB.meta.up.eff * .1);
  if (G.golden) { mult *= 2; G.golden = false; }
  if (G.items.omamori > 0) { mult *= 1.6; G.items.omamori--; toast("🍱 差し入れの力！ 伸び 1.6倍"); }
  if (G.over) mult *= .6;
  const base = 2.5 + r.score / 13;
  const gains = [];
  const d1 = addStat(cmd.main, gainFor(cmd.main, base * mult));
  gains.push([STATS.find(s => s.k === cmd.main).n, d1]);
  if (cmd.sub === "*") {
    STATS.forEach(s => { if (s.k !== cmd.main) { const d = addStat(s.k, gainFor(s.k, base * mult * .32)); if (d) gains.push([s.n, d]); } });
  } else {
    const d2 = addStat(cmd.sub, gainFor(cmd.sub, base * mult * .45));
    if (d2) gains.push([STATS.find(s => s.k === cmd.sub).n, d2]);
  }
  let fans = 0;
  if (r.score >= 70) { fans = Math.round((r.score - 60) * ri(3, 7) * (1 + fx.fan)); G.fans += fans; }
  if (r.score >= 95 && r.correct === r.total) { G.pf[cmd.g] = (G.pf[cmd.g] || 0) + 1; G.perfectLesson++; }
  G.totalQ += r.total; G.totalOK += r.correct;
  G.bestCombo = Math.max(G.bestCombo, r.best);
  const lvBefore = lessonLv();
  G.recentScores = (G.recentScores || []).concat(r.score).slice(-5);
  const lvAfter = lessonLv();
  if (lvAfter > lvBefore) setTimeout(() => toast(`📈 問題のレベルが上がった！ Lv.${lvBefore} → Lv.${lvAfter}`), 900);
  else if (lvAfter < lvBefore) setTimeout(() => toast(`🌱 いったん基礎にもどろう　Lv.${lvBefore} → Lv.${lvAfter}`), 900);
  if (G.over && Math.random() < .35) G.cond = clamp(G.cond - 1, 0, 4);
  showResult({ title: `${cmd.e} ${cmd.n}`, r, gains, fans, after: () => checkSkills(() => maybeAdvice(() => endDay())) });
}

/* ================= くら寿司イベント（タクトと回転ずし） ================= */
/* ================= 先輩の合格ストーリー（30本・毎プレイ3〜4本） ================= */
const GOKAKU_STORIES = [
  { n: "E判定からの女子学院", t: "さくらさん（当時小6）の話。\n\n6年生の9月、模試はE判定。合格率20%未満。塾の面談で「志望校を変えましょう」と言われて、トイレで泣いた。\n\nでもその夜、お母さんに言ったんだって。「変えない。だって、まだ2月じゃないもん」。\n\nそこから彼女がやったことは、たった2つ。①まちがえた問題を全部ノートに貼る ②同じ問題を3回解き直す。新しい問題集は1冊も買わなかった。\n\n11月、D判定。12月、C判定。1月の最終模試でもB判定止まり。\n\nでも2月1日、彼女は受かった。\n\n合格発表の日の日記にこう書いてある。\n「判定は過去の私の成績。試験を受けるのは、当日の私」" },
  { n: "偏差値35から東京女学館へ", t: "ゆいさん（当時小6）は、5年生の終わりの偏差値が35だった。\n\n計算は遅いし、漢字は覚えられない。「私、頭悪いから」が口ぐせだった。\n\n転機は、文化祭。東京女学館の白い制服の先輩たちが、楽しそうに実験を見せてくれた。帰り道、ゆいさんは初めて自分から言った。「ここに行きたい」。\n\nそこから、口ぐせが変わった。「頭悪いから」→「まだ解けないだけ」。\n\nやったことは地味だった。毎朝、計算10問。毎晩、漢字5個。土日はまちがい直し。それを300日、続けた。\n\n偏差値は35→39→43→47と、階段みたいに上がった。\n\n2月、彼女はあの白い制服を着た。\n\n「行きたい学校を見つけた日が、私の受験が始まった日でした」" },
  { n: "算数が大きらいだった子", t: "みおさん（当時小6）は、算数のテストで28点を取ったことがある。\n\n答案を隠して、ランドセルの底でくしゃくしゃにした。「算数なんて大きらい。一生使わないもん」。\n\n塾の先生は怒らなかった。かわりに、毎日たった3問の「できる問題」を出した。「満点しか取れない宿題」だ。\n\n3問なら、できる。毎日、花マルがもらえる。1ヶ月たつと、みおさんは気づいた。「私、算数で花マルもらうの、好きかも」。\n\n3問は5問になり、10問になった。半年後、模試の算数で偏差値50を超えた。1年後、第一志望の合格通知が届いた。\n\n今、みおさんは中学の数学係だ。\n\n「きらいだったんじゃなくて、できなくて悲しかっただけだった」" },
  { n: "本番で頭が真っ白になった子", t: "はなさん（当時小6）の本番の話。\n\n2月1日の第一志望。1時間目の国語で、緊張のあまり頭が真っ白になった。文章が、まったく頭に入らない。時計の音だけが響く。「終わった……」と思った。\n\nそのとき、塾の先生の声を思い出した。\n「真っ白になったら、鉛筆を置いて、10秒だけ目を閉じる。10秒は、もったいなくない。パニックのまま解く10分のほうが、もったいない」\n\nはなさんは目を閉じた。ゆっくり3回、呼吸した。目を開けたら、文章が「日本語」に戻っていた。\n\n結果は、合格。\n\n「あの10秒が、私の受験でいちばん勇気のいる10秒でした」" },
  { n: "塾なし・図書館の子", t: "そらくん（当時小6）の家は、塾に通う余裕がなかった。\n\n彼の塾は、市立図書館だった。学校が終わると図書館に行き、閉館の音楽が鳴るまで勉強した。参考書は、図書館のものと、先輩のおさがり。\n\n「まわりはみんな塾に行ってる。不安じゃなかった?」と聞かれて、彼はこう答えた。\n\n「不安だったよ。でも、ぼくには『質問ノート』があった」\n\nわからない問題をノートに書きためて、週1回、学校の先生に聞きに行った。先生は全部に付き合ってくれた。\n\n2月、彼は難関校に合格した。入学式の日、彼は図書館に寄って、司書さんに合格を報告した。司書さんは泣いた。\n\n「環境は、言い訳にも、武器にもなる」" },
  { n: "12月に大失速した子", t: "りこさん（当時小6）は、12月に成績が急落した。\n\n原因は、焦り。「もう時間がない」と思って、新しい問題集を3冊同時に始めた。全部が中途半端になり、模試の偏差値は4つ下がった。\n\n塾の先生が、りこさんの机の問題集を全部閉じて言った。\n「新しいことは、もう何もしなくていい。きみには『まちがえた問題』という、世界にひとつの参考書がある」\n\n冬休み、りこさんは過去のまちがいだけを解き直した。テキストは1冊も増やさなかった。\n\n1月の最終模試で、自己最高偏差値。2月、合格。\n\n「増やす勇気より、増やさない勇気のほうが、ずっと難しかった」" },
  { n: "インフルエンザの2月", t: "たいちくん（当時小6）は、2月1日の朝、38.5度の熱を出した。\n\nインフルエンザだった。第一志望の受験は、別室受験。頭はぼんやり、鼻はつまり、最悪のコンディション。\n\nでも彼は、あることを思い出していた。12月の塾の授業で、先生が言った言葉。\n\n「本番は、何が起きるかわからない。だから練習では『最悪の状態でも解ける』ところまで仕上げるんだ。調子のいい日の実力は、本当の実力じゃない」\n\n彼の計算は、熱があっても手が勝手に動くレベルまで仕込まれていた。毎朝の計算300日の貯金だった。\n\n結果は、合格。\n\n「実力っていうのは、最悪の日に出る力のことなんだって、体で知った」" },
  { n: "友だちと張り合った子", t: "ことはさんと、みくさんは、同じ塾のライバルだった。\n\nテストのたびに1点差で勝ったり負けたり。悔しくて泣いた日もある。「みくにだけは負けたくない」が、ことはさんの本音だった。\n\nでも6年生の秋、みくさんが体調を崩して塾を休みがちになった。ことはさんは、自分でも意外な行動をとった。毎週、授業のノートをコピーして、みくさんの家のポストに入れたのだ。\n\n「ライバルがいない受験なんて、つまらないから」\n\nみくさんは戻ってきた。2人は最後まで1点差で競い合い——2月、2人とも第一志望に受かった。\n\n合格発表の日、2人で撮った写真には、こう書いてある。\n『戦友』" },
  { n: "過去問0点スタート", t: "けんとくん（当時小6）が初めて第一志望の過去問を解いたのは、10月。\n\n算数、100点満点中12点だった。\n\n「無理だ」と思った。でも塾の先生は、答案を見てニヤリと笑った。\n「いいね。伸びしろが88点もある」\n\nそこから彼は、過去問を「宝の地図」に変えた。まちがえた問題を単元ごとに分類したら、「速さ」と「立体」に穴が集中していることがわかった。敵は88点ぶんじゃなくて、実は2単元だった。\n\n11月は速さだけ。12月は立体だけ。1月にもう一度、同じ年の過去問を解いた。\n\n78点だった。\n\n2月、合格。「12点の答案を捨てなくてよかった。あれが地図だった」" },
  { n: "第一志望に落ちた子の話", t: "これは、少しだけ苦い、でも大切な話。\n\nあおいさん（当時小6）は、第一志望に落ちた。2月3日の夜、番号がなかった。玄関で泣き崩れて、立てなかった。\n\n第二志望の学校に入学した春、あおいさんはまだ少し、心に穴があいていた。\n\nでも——入学した学校で、吹奏楽部に出会った。親友に出会った。大好きな英語の先生に出会った。\n\n2年後、あおいさんは日記にこう書いた。\n「あの日、番号がなくて世界が終わったと思った。でも世界は終わってなかった。今の私は、今の学校が大好きだ。あのとき全力で頑張った私のことも、大好きだ」\n\n受験の合否は、人生の合否じゃない。\n全力で頑張った経験は、どの学校に行っても、一生の武器になる。" },
  { n: "計算ミスの女王", t: "まなさん（当時小6）のあだ名は「計算ミスの女王」だった。\n\n実力はあるのに、毎回テストで20点ぶんミスをする。「私、そそっかしいから」と笑ってごまかしていた。\n\n転機は、塾の先生のひとこと。\n「ミスを『性格』のせいにしたら、一生直らない。ミスは『技術』で消すんだ」\n\nまなさんは、自分のミスを3週間ぶん集めて分析した。すると、ミスの7割が「くり上がりの書き忘れ」と「単位の見落とし」の2種類だけだと判明した。\n\n対策はシンプル。くり上がりは必ず書く。単位には必ず丸をつける。この2つを「ルール」にした。\n\n1ヶ月後、ミスは20点ぶんから4点ぶんに減った。偏差値は5上がった。2月、合格。\n\n「ミスは、私の性格じゃなくて、ただのクセだった」" },
  { n: "夜型から朝型へ", t: "ゆうまくん（当時小6）は、夜中の12時まで勉強するタイプだった。\n\n「夜のほうが集中できる」と思っていた。でも6年生の秋、模試の算数でぼんやりして大失敗。試験は朝9時。彼の脳は、朝9時に眠っていた。\n\n塾の先生に言われた。「入試は朝にある。朝に強い脳を作るのも受験勉強だ」\n\n彼は45日かけて、少しずつ生活を変えた。夜は10時に寝る。朝6時に起きて、計算と漢字だけやる。最初の1週間は眠くて仕方なかったが、3週間目から朝の頭が冴え始めた。\n\n1月の最終模試、朝イチの算数で自己ベスト。2月も、朝から頭はフル回転した。\n\n合格発表を見たのも、朝だった。\n「朝は、毎日くる本番の練習だった」" },
  { n: "スマホと戦った子", t: "りんさん（当時小6）の敵は、スマホだった。\n\n「5分だけ」のつもりが気づけば1時間。夜、罪悪感で泣きたくなる。意志の力では、どうしても勝てなかった。\n\nりんさんがすごかったのは、「自分の意志の弱さ」を認めたこと。そして意志ではなく、仕組みで戦ったこと。\n\n①スマホはリビングで充電（自分の部屋に持ち込まない）\n②勉強のスタート時に、お母さんに預ける\n③夜8時半に返してもらって、30分だけ自由\n\nルールを決めた日から、戦いは終わった。我慢したんじゃない。戦場からスマホを消したのだ。\n\n偏差値は3ヶ月で6上がった。2月、合格。\n\n「意志が弱くても、仕組みが強ければ勝てる」" },
  { n: "音読しかしなかった子", t: "こはるさん（当時小6）は、国語の読解が大の苦手だった。\n\n選択肢は全部同じに見えるし、記述は白紙。模試の国語の偏差値は38。\n\n塾の先生の処方箋は、意外なものだった。\n「毎日10分、音読しなさい。問題は解かなくていい」\n\n半信半疑で、こはるさんは毎晩、物語文を声に出して読んだ。お母さんが夕飯を作るキッチンで、毎日10分。\n\n1ヶ月目、変化なし。2ヶ月目、あれ、文章が「景色」として見えるようになってきた。3ヶ月目、登場人物の気持ちが、声の調子でわかるようになった。\n\n入試本番、国語は得点源になっていた。\n\n「読めるようになったんじゃなくて、文章と仲良くなった感じ」" },
  { n: "身長より高く積んだノート", t: "だいきくん（当時小6）は、卒業式の日に、あるものを写真に撮った。\n\n2年間で使い切ったノートと問題集の山。積み上げたら、145cm。彼の身長より、少しだけ高かった。\n\n彼は特別な才能があったわけじゃない。模試で泣いたことも、宿題をサボってお母さんとケンカしたこともある。\n\nでも、彼には「儀式」があった。ノートを1冊使い切るたびに、表紙に日付と、ひとことを書いて、本棚の「殿堂」に並べる。\n\n「殿堂」が増えていくのが、うれしかった。スタンプカードみたいで。\n\n2月の朝、試験会場に向かう前、彼は殿堂の前に立って深呼吸した。\n\n「あの山が、おれの自信だった。だって、ぜんぶ、おれがやったんだから」" },
  { n: "先生を質問攻めにした子", t: "ももさん（当時小6）は、塾でいちばん質問する子だった。\n\n授業のあと、毎日、先生をつかまえる。「ここがわからない」「なんでこうなるの?」。恥ずかしいと思ったことはなかった……わけじゃない。最初はすごく勇気がいった。\n\n「こんなこともわからないの、って思われたらどうしよう」\n\nでも、初めて質問した日、先生はこう言った。\n「いい質問だね。それ、みんなわかってないところだよ」\n\nあれ、質問って、恥ずかしくないんだ。それどころか、質問すると先生の説明が「私専用」になる。こんなにお得なことはない。\n\n入試直前、ももさんの質問ノートは3冊になっていた。2月、合格。\n\n「『わからない』って言える人が、いちばん強いと思う」" },
  { n: "500円玉貯金と過去問", t: "あかねさん（当時小6）の家には、大きな瓶があった。\n\n過去問を1年ぶん解くたびに、お父さんが500円玉を入れる。「合格したら、この貯金で家族で焼肉に行こう」という約束だった。\n\n最初は500円のために解いていた。でも、瓶がだんだん重くなるにつれて、不思議な気持ちが芽生えた。\n\nこの瓶、私の努力の重さだ。\n\n1月末、瓶には24枚の500円玉が入っていた。24年ぶんの過去問。第一志望の10年ぶんは、2周した。\n\n2月、合格。家族で行った焼肉は、人生でいちばんおいしかった。\n\n「努力はね、目に見える形にすると、強くなるんだよ」と、あかねさんは笑う。" },
  { n: "苦手表を作った子", t: "しゅんくん（当時小6）は、6年生の夏、成績が伸び悩んでいた。\n\n「頑張ってるのに伸びない」。毎日3時間勉強しているのに、模試の偏差値は横ばい。\n\n塾の先生が、彼の勉強を1週間観察して、こう言った。\n「きみは『できる問題』ばかり解いてる。気持ちいいからね。でも筋トレと同じで、効くのは『ちょっと苦しい負荷』だけだ」\n\n図星だった。得意な計算ばかりやって、苦手な図形から逃げていた。\n\n彼は「苦手表」を作った。単元を○△×で分類し、×だけを毎日1つ潰す。気持ちよくない勉強の始まりだった。\n\n2ヶ月後、×は11個から3個に減り、偏差値は7上がった。\n\n「伸びる勉強は、ちょっと苦しい。逆に言えば、苦しさは効いてる証拠」" },
  { n: "受験をやめたいと言った夜", t: "みずきさん（当時小6）は、11月のある夜、お母さんに言った。\n\n「受験、やめたい」\n\n成績が下がり、友だちと遊べず、もう限界だった。言った瞬間、涙があふれた。\n\nお母さんは、怒らなかった。「そっか。じゃあ今週は、塾を休もう」とだけ言った。\n\n1週間、みずきさんは思いきり遊んだ。公園に行き、映画を見て、ゲームをした。\n\n4日目の夜、ふしぎなことが起きた。……なんだか、そわそわする。5日目、こっそり計算ドリルを開いた。6日目、気づいた。\n\n「私、やめたいんじゃなくて、疲れてただけだ」\n\n7日目、自分から塾に戻った。2月、合格。\n\n「休むのは、逃げじゃなかった。続けるための作戦だった」" },
  { n: "本番に強い子の秘密", t: "ひなたさん（当時小6）は「本番に強い子」と言われていた。\n\n模試より本番のほうが点が出る。緊張しないの?と聞かれると、彼女は「めっちゃ緊張するよ」と答えた。\n\n彼女の秘密は、「緊張の練習」をしていたこと。\n\n模試のたびに、本番と同じ服を着て、同じ朝ごはんを食べ、同じ鉛筆を持った。会場には早めに着いて、トイレの場所を確認する。試験開始前には、必ず同じ言葉を心の中で唱えた。\n\n「緊張してるね、私。本気の証拠だね」\n\n本番の日、彼女にとってそれは「いつもの模試」と同じ手順だった。緊張はあった。でも、緊張との付き合い方を、体が知っていた。\n\n「本番に強いんじゃなくて、本番を『いつも通り』にしただけ」" },
  { n: "サクラサク、の電報", t: "これは、あるお父さんから聞いた話。\n\n娘のりょうこさん（当時小6）は、1月の埼玉入試で全滅した。3連敗。自信を完全に失い、「2月も全部落ちる」と泣いた。\n\nその夜、お父さんは古いアルバムを取り出した。そこには、りょうこさんが逆上がりを練習する写真があった。5歳のりょうこさんは、107回失敗して、108回目に成功したのだという。手にマメを作りながら。\n\n「おまえは昔から、できるまでやる子だった。3回落ちた? おまえの逆上がりは107回落ちてる」\n\nりょうこさんは笑ってしまった。泣きながら笑った。\n\n2月1日、第一志望、合格。\n\n彼女は今でも、あの写真を机に飾っている。「私の中には、108回目のわたしがいる」" },
  { n: "算数1問と向き合った45分", t: "とうまくん（当時小6）には、忘れられない45分がある。\n\n日曜日の夜、1問の図形問題が解けなかった。解説を見ればすぐ終わる。でも、なぜかその日は「自力で解きたい」と思った。\n\n15分、手が止まる。20分、補助線を1本引いてみる。ちがう。30分、別の線。ちがう。40分——あ。\n\n「見えた」瞬間のことを、彼は今でも覚えている。世界がパッと明るくなって、鉛筆が勝手に動いた。答えが合っていたときの、あの鳥肌。\n\n「あの1問から、算数が『作業』じゃなくて『冒険』になった」\n\n彼はその後、算数を得点源にして合格した。\n\n解説を見るのは、悪いことじゃない。でも人生に何回か、「自力で戦う1問」があっていい。その1問が、きみを変えるかもしれない。" },
  { n: "双子の別々の春", t: "ふたごの、ちかさんとりかさん（当時小6）の話。\n\n2人は同じ塾で、同じ学校を目指していた。でも2月、ちかさんは合格し、りかさんは不合格だった。\n\n家の中に、うれしさと悲しさが同時にあった。ちかさんは喜べなかった。りかさんは笑おうとして、笑えなかった。\n\nその夜、りかさんが先に口を開いた。\n「おめでとうって、言わせて。じゃないと私、自分の3年間まで嫌いになっちゃう」\n\n2人で泣いた。ちかさんも「ありがとう」と言って泣いた。\n\nりかさんは別の学校に進み、テニス部のエースになった。今、2人は別々の制服で、同じ塾の前で待ち合わせて帰る。\n\n「受験は勝ち負けじゃなくて、それぞれの道の始まりだった」と、2人は言う。" },
  { n: "漢字テスト0点からの逆転", t: "はるとくん（当時小5）は、塾の漢字テストで0点を取ったことがある。\n\n10問中0問。返された答案を、彼は今でも持っている。捨てなかった理由は「悔しかったから」。\n\n彼が変えたのは、覚え方だった。それまでは前日に10個まとめて書いて覚えるフリをしていた。それを「1日2個×5日」に変えた。しかも、ただ書くんじゃなくて、その漢字を使った文を作る。\n\n『妹が微妙な顔で牛乳を飲んだ』\n\nくだらない文ほど、忘れない。彼のノートは変な例文だらけになり、塾の友だちに回し読みされるようになった。\n\n半年後、彼は漢字テスト20連続満点を達成する。\n\n「0点の答案は、おれの出発点。あれがなかったら、始まってなかった」" },
  { n: "面接で泣いた子", t: "ゆずさん（当時小6）が受けた学校には、面接があった。\n\n「志望理由を教えてください」\n\n練習した通りに話すつもりだった。でも、先生の目があまりに優しくて、ゆずさんは急に、この2年間のことを思い出してしまった。泣きながら塾に行った日。眠い朝。励ましてくれた家族。\n\n言葉に詰まって、涙が出た。「終わった」と思った。\n\nでも彼女は、涙を拭いて、練習していない言葉で話し始めた。\n「……うまく言えません。でも、この学校に来たくて、私、2年間がんばりました」\n\n面接官の先生は、深くうなずいた。\n\n合格だった。\n\n完璧な言葉より、本気の言葉。それは面接だけじゃなくて、たぶん、人生ぜんぶでそうなのだ。" },
  { n: "リビング勉強法", t: "そうたくん（当時小6）は、自分の部屋で勉強できなかった。\n\nベッドがある。マンガがある。誘惑が多すぎた。\n\n彼が選んだのは、リビングのテーブル。お母さんが料理する音、妹のテレビの音。一見うるさそうだが、彼には合っていた。\n\n「静かすぎると、逆に集中できない。それに、リビングだと『見られてる』から、サボれない」\n\n実は、入試会場も静かじゃない。となりの子の鉛筆の音、咳、監督の足音。リビングで鍛えた彼の集中力は、雑音に強かった。\n\n2月、彼は雑音の中で自己ベストを出して合格した。\n\n「集中力って、シーンとした場所でしか出ないようじゃ、本番で使えないんだよね」" },
  { n: "不合格通知を貼った子", t: "れんくん（当時小6）は、1月の前受け校に落ちた。\n\nふつう、不合格通知は隠す。でも彼は、その通知を勉強机の前に貼った。お母さんは「やめなよ」と言ったが、彼は「これがいい」と言った。\n\n「これを見ると、『あの悔しさをもう一回味わいたいか?』って自分に聞ける。答えはNOだから、机に向かえる」\n\n2月1日の朝、彼は通知の横に、小さくメモを貼り足した。\n\n『今日、これを過去にする』\n\nその日の夜、第一志望の合格発表。番号は、あった。\n\n彼は不合格通知をていねいにはがして、ノートの最後のページに貼り直した。\n\n「これは恥じゃなくて、おれの物語の第1章だから」" },
  { n: "計算タイムアタックの女王", t: "みらいさん（当時小6）の塾には、「計算タイムアタック」の文化があった。\n\n毎朝、同じ100問を解いて、タイムを計る。みらいさんは最初、クラスで最下位。19分もかかった。\n\n彼女は、タイムを手帳に記録し始めた。19分、18分半、17分……。折れ線グラフが、少しずつ下る。\n\nそれが、うれしくてたまらなかった。\n\n「昨日の私に勝つのが、毎朝の楽しみだった。ゲームのタイムアタックと同じ」\n\n3ヶ月後、彼女のタイムは8分になった。クラス2位。1位の男の子とは、卒業まで抜きつ抜かれつのライバルになった。\n\n計算が速くなると、テストで「考える時間」が増える。彼女の算数の偏差値は、計算だけで6上がった。\n\n「才能じゃないよ。グラフが下がるのが楽しかっただけ」" },
  { n: "お守りのハンカチ", t: "かのんさん（当時小6）のお守りは、おばあちゃんのハンカチだった。\n\n受験勉強を始めた小4の春、おばあちゃんがくれた。「これで涙を拭いたら、また頑張れるよ」って。\n\n実際、そのハンカチは何度も涙を拭いた。模試の帰り道。夜のリビング。おばあちゃんのお葬式の日も。\n\nおばあちゃんは、合格を見届けられなかった。\n\n2月1日、かのんさんは試験会場の机の上に、そっとハンカチを置いた（試験官に確認して、だけど）。\n\n「おばあちゃん、見てて」\n\n合格発表の日、かのんさんはハンカチを持って泣いた。うれし涙をあのハンカチで拭いたのは、初めてだった。\n\n大切な人の想いは、いちばん強いお守りになる。" },
  { n: "最後の1ヶ月で20点伸びた子", t: "いつきくん（当時小6）の1月は、伝説になっている。\n\n12月末の過去問、第一志望の算数は52点。合格者平均は70点。「1ヶ月じゃ、もう無理」と誰もが思った。本人以外は。\n\n彼は1月、たった3つのことしかしなかった。\n\n①第一志望の過去問10年ぶんの「大問1と2だけ」を毎日解く（基本問題を絶対落とさないため）\n②まちがえた問題の解き直しを、翌朝もう一回\n③新しい問題集は、開かない\n\n「全部やる」を捨てて、「出るところだけ」に絞った。\n\n2月1日の本番、算数は74点。1ヶ月で22点伸びた。合格。\n\n「最後の1ヶ月は、伸びないんじゃない。伸ばし方が変わるだけ」\n\n入試は、前日まで伸びる。これは彼が証明した。" },
  { n: "帰り道の10分復習", t: "ななみさん（当時小6）の成績が急に伸び始めたとき、塾の先生は不思議に思った。勉強時間は増えていないのに、なぜ?\n\n秘密は、帰り道にあった。\n\n塾から家まで、歩いて10分。ななみさんはその10分で、「今日の授業でいちばん大事だったこと」を頭の中で再生していた。\n\n「先生が黒板に書いた、あの図。あの解き方。えっと、最初に何をするんだっけ……」\n\n思い出せないところは、家に着いてすぐノートで確認。この「思い出す練習」が、実は記憶の最強トレーニングだった。\n\n脳は、「入れたとき」じゃなくて「出したとき」に覚える。\n\n「机に向かう時間だけが勉強じゃないって、帰り道が教えてくれた」" },
  { n: "山脇の紺のワンピース", t: "りささん（当時小6）が山脇学園に憧れたきっかけは、電車で見かけた紺色のワンピースの制服だった。\n\n「あの制服の人、背筋がまっすぐできれいだな」\n\n学校説明会で、りささんは理科の実験施設に一目ぼれする。「ここで実験したい。ぜったいここがいい」。でも当時の偏差値は、合格ラインまであと8足りなかった。\n\n彼女は帰り道に文房具屋で紺色のペンを買った。「山脇ペン」と名づけて、まちがい直し専用にした。ノートの赤ペンならぬ紺ペンが増えるたび、あの制服に近づく気がした。\n\n紺ペンは、半年で4本からになった。\n\n2月、彼女は本物の紺のワンピースを手に入れた。今、あの実験室が彼女の放課後の居場所だ。\n\n「憧れは、いちばん長持ちする燃料でした」" },
  { n: "桜蔭と「勉強が好き」の意味", t: "ふみさん（当時小6）は、桜蔭を目指していた。女子最難関。まわりから「無理しないで」と言われるたび、少しずつ自信が削れていった。\n\n6年生の夏、塾の先生に聞いた。「桜蔭って、どんな子が受かるんですか。天才ですか」\n\n先生は笑って言った。\n「天才じゃないよ。『わからないことを、放っておけない子』だ。きみ、この前、電車の中づり広告の割引計算してたろ。あれだよ、あれ」\n\nふみさんは、はっとした。勉強=つらいもの、と思いこんでいた。でも本当は、わかった瞬間が好きで仕方なかったのだ。\n\nその日から、彼女は「勉強をがんばる」のをやめて、「わからないを潰すゲーム」を始めた。\n\n2月1日、本郷の坂を上って、彼女は桜蔭生になった。\n\n「好きって気づいたら、強くなった」" },
  { n: "昭和女子と三軒茶屋の約束", t: "ひまりさん（当時小6）のお母さんは、昭和女子の卒業生だった。\n\nでも、お母さんは一度も「ここを受けなさい」と言わなかった。文化祭に連れて行ってくれただけ。校門で「世の光となろう」の言葉を見上げて、ひまりさんは自分から言った。「私、ここ受ける」\n\n模試の成績は、ずっとギリギリだった。12月、C判定。お母さんは初めて母校の話をした。\n\n「お母さんもね、ギリギリだったよ。でも、あの学校で友だちと過ごした6年間が、人生の宝物になった。だから、あなたに押しつけたくなかったの。自分で選んでほしかったから」\n\n2月、合格。三軒茶屋の駅で、母娘で泣いた。\n\n「押しつけられなかったから、私の受験になった」" },
  { n: "跡見の「ごきげんよう」", t: "あやかさん（当時小6）が跡見学園の説明会で驚いたのは、生徒たちのあいさつだった。\n\n「ごきげんよう」\n\n初めて聞いたとき、正直「お嬢さまっぽくて自分には合わないかも」と思った。でも在校生に質問したとき、その先輩は目を見て、まっすぐ答えてくれた。マニュアルじゃなくて、心のこもった言葉で。\n\n「あいさつがきれいな学校は、人がきれい」。お父さんの言葉に、あやかさんはうなずいた。\n\n受験勉強の最後の3ヶ月、彼女は毎朝、机に向かう前に鏡に向かって「ごきげんよう」と練習した。合格した自分の練習だ。笑ってしまう日もあったが、不思議と背筋が伸びた。\n\n2月、彼女は本物の「ごきげんよう」を言う側になった。\n\n「なりたい自分のまねをしてたら、なれちゃいました」" },
  { n: "フェリスと山手の坂道", t: "まりんさん（当時小6）は、横浜・山手のフェリス女学院を目指していた。\n\n説明会の日、石川町の駅から続く急な坂道を上りながら、お母さんが息を切らして言った。「この坂、毎日はきついね」。でもまりんさんは、坂の上から見えた景色に心を撃ち抜かれていた。\n\n港の見える街。112段の階段を上った先の校舎。「For Others——他者のために」という言葉。\n\n成績が伸び悩んだ秋、彼女は勉強机に坂道の写真を貼った。\n\n「この坂を、制服で上る」\n\nつらい夜は写真を見た。過去問に落ちこんだ夜も、坂の上の景色を思い出した。\n\n2月。合格発表の画面に番号を見つけた瞬間、彼女が最初に言った言葉は「坂、上れる!」だった。\n\n今、彼女は毎朝あの坂を上っている。ぜんぜん、きつくないらしい。" },
  { n: "横浜共立の赤レンガ", t: "ゆきなさん（当時小6）が横浜共立学園に出会ったのは、雨の学校見学だった。\n\n山手の丘の上、歴史ある美しい校舎。雨にぬれた赤い屋根を見て、「物語の中の学校みたい」と思った。150年近い歴史があると聞いて、鳥肌が立った。\n\n「この校舎で勉強した先輩が、何万人もいるんだ」\n\nゆきなさんは歴史が好きな子だった。それからの勉強で、疲れると想像した。関東大震災も戦争も乗り越えたあの校舎。その机に、自分が座る姿。\n\n模試でD判定を取った日も、「150年の歴史から見たら、D判定の1回なんて小さい小さい」と笑い飛ばした。この発想は最強だった。\n\n2月、合格。\n\n「大きくて古いものに憧れると、自分の悩みが小さく見えるんです」と彼女は言う。名言だと思う。" },
  { n: "横浜雙葉と海の見える教室", t: "ここなさん（当時小6）は、転勤族の子だった。\n\n小4まで3回転校した。「また転校するかもしれないから」と、友だちを作るのが少しこわかった。\n\n横浜雙葉の文化祭に行った日、在校生の楽しそうな姿を見て、初めて思った。「6年間、同じ場所で、同じ友だちと過ごせるんだ」\n\n彼女にとって中学受験は、成績の戦いじゃなくて、「ずっとここにいられる場所」を自分の力でつかみ取る挑戦だった。\n\n山手の丘、海の見える学校。「ここなら、根っこを張れる」\n\n勉強がつらい日は、まだ見ぬ親友を想像した。「いま解いてるこの1問の先に、その子がいる」\n\n2月、合格。入学式で隣の席になった子と、彼女は今も一番の親友だ。\n\n1問の先に、ほんとうに、いた。" },
  { n: "吉祥女子と自由の重さ", t: "つむぎさん（当時小6）は、学校説明会で吉祥女子の先生の言葉に衝撃を受けた。\n\n「うちは自由な学校です。でも自由とは、自分で考えて、自分で決めて、自分で責任を取ることです」\n\n小6のつむぎさんに、その言葉は少し難しかった。でも、かっこいいと思った。\n\nその日から、彼女の勉強が変わった。お母さんに言われて机に向かうのをやめて、自分で1週間の計画表を作った。最初の計画はボロボロで、3日で崩壊した。2枚目も崩壊した。5枚目くらいから、コツがわかってきた。\n\n「無理な計画は、自由じゃなくてただの夢。守れる計画が、自由の第一歩」\n\n2月、合格。彼女の合格は、5枚の失敗した計画表の上に建っている。\n\n「自由って、練習しないと使えないんだよ」" },
  { n: "大妻と「恥を知れ」", t: "せなさん（当時小6）は、大妻中学の校訓を初めて見たとき、こわいと思った。\n\n「恥を知れ」\n\nでも説明会で意味を聞いて、震えた。これは人を責める言葉じゃない。「自分に恥じることをしていないか、自分に問いなさい」という、自分への言葉だった。\n\nせなさんには、隠していることがあった。塾の宿題の答えを、たまに写していたのだ。バレたことはない。でも、この言葉の前で、彼女は自分に負けている自分に気づいた。\n\nその夜から、答えを写すのをやめた。わからない問題は空欄で出して、「わかりません、教えてください」と言うことにした。成績は一度下がって、それから本物の上がり方をした。\n\n2月、合格。\n\n「誰も見てなくても、自分は見てる。それに気づいた日から、私の勉強は本物になった」" },
  { n: "品川女子と28歳の私", t: "いちかさん（当時小6）は、品川女子学院の説明会で不思議な話を聞いた。\n\n「この学校は、28歳のあなたを見て教育をします」\n\n28歳? 小6の私の、倍以上。想像もつかない。でも家に帰って、いちかさんは初めて「大人になった自分」を絵に描いてみた。\n\n描いたのは、白衣を着て、犬の病気を治している自分だった。獣医さん。飼い犬のモコが病気になったとき、何もできなかった悔しさを思い出した。\n\n「私、そのために理科と算数がいるんだ」\n\n目的ができた瞬間、勉強の意味が変わった。算数は「受験のため」じゃなくて「モコみたいな子を救うため」になった。\n\n2月、合格。彼女の机には今、白衣の絵が貼ってある。\n\n夢から逆算すると、今日の1問の意味が変わる。" },
  { n: "豊島岡と5分の運針", t: "のあさん（当時小6）は、豊島岡女子の朝の伝統を知って、意味がわからなかった。\n\n毎朝5分、全校生徒が無言で白い布に赤い糸で針を運ぶ。「運針」。\n\n「え、縫うの? 毎朝? なんで?」\n\n説明会で先生が言った。「5分間、雑念を捨てて、一針に集中する。基礎の大切さと、心を整えることを学びます」\n\nのあさんは、ためしに家で真似してみた。お裁縫セットの針と布で、5分。最初は雑念だらけだった。でも不思議なことに、運針のあとに解く計算は、ミスが減った。\n\n心を整えてから始める——それだけで、同じ実力でも出る結果が変わる。彼女は試験当日も、開始前に心の中で針を運んだ。\n\n2月、合格。今、彼女は本物の運針をしている。\n\n「たった5分の静けさが、1日を変えるんです」" },
  { n: "東洋英和と楓の木", t: "りんかさん（当時小6）が東洋英和女学院を志望したのは、六本木という場所からは想像できない、静かで美しい校舎に驚いたからだった。\n\n象徴は、楓（かえで）。\n\n説明会の帰り、お父さんが言った。「楓はね、紅葉するまでに時間がかかる木なんだ。でも、いちばんきれいに色づく」\n\nりんかさんは、成績が上がるのが遅い子だった。同じ問題を人の倍やって、やっと定着する。「私、要領悪いから」が悩みだった。\n\nでもその日から、彼女は自分を「楓」だと思うことにした。ゆっくりでいい。時間がかかっていい。そのぶん、深く根を張って、きれいに色づく。\n\n倍やることは、変わらなかった。でも「倍かかる自分」を責めるのを、やめた。\n\n2月、合格。校庭の楓が、彼女を迎えた。\n\n「遅い子は、ダメな子じゃない。深く育ってる子」" },
];
function maybeGokaku(next) {
  /* 7日ごとに1本保証＋低確率で追加（1プレイ3〜4本） */
  const target = Math.floor(G.day / 7) + (G.day >= 27 ? 1 : 0);
  const due = (G.gokakuCount || 0) < target;
  if (!due && Math.random() >= .08) return false;
  DB.meta.gokakuSeen = DB.meta.gokakuSeen || [];
  let avail = GOKAKU_STORIES.map((_, i) => i).filter(i => !DB.meta.gokakuSeen.includes(i));
  if (!avail.length) { DB.meta.gokakuSeen = []; avail = GOKAKU_STORIES.map((_, i) => i); }
  const gi = pick(avail);
  DB.meta.gokakuSeen.push(gi);
  G.gokakuCount = (G.gokakuCount || 0) + 1;
  const st = GOKAKU_STORIES[gi];
  const readers = ["shino", "kanade", "masaki", "takuto"].filter(id => !CANDS[id] || G.alive.includes(id));
  const rd = readers[0] || "kanade";
  showEvent({
    c: rd,
    t: `📖 先輩の合格ストーリー\n──『${st.n}』──\n\n${st.t}`,
    ch: [
      { t: "🌸 ……わたしも、続く", fx: { st: { me: 5 }, cond: 1 }, after: next },
      { t: "🔥 明日の1問が、楽しみになった", fx: { st: { me: 4 } }, after: next },
    ]
  });
  return true;
}

