    "あかり「大阪のたこ焼きって、そんなにおいしいの？」\n\nダイゴ「……ええ質問や。座り。\n\n大阪のたこ焼きはな、外はカリッ、中はトロッや。\n今度、おれが焼いたるわ。ソース多め、かつお節は雪や思て降らせる。\n\n合格祝いは、ダイゴ特製たこ焼きパーティーや。約束やで！」",
