  "（休み時間、もかとももかが手品を見せてくれた）\n\nもか「トランプ、1枚えらんでください」\nももか「……はい、あなたのカードは、これ！」\n\n（違うカードだった）\n\nもか「「えっ」」\n（練習しなおして3回目、見事成功。教室中が拍手だった）",
  "（りょうたろうとゆうたが、計算対決を挑んできた）\n\nりょうたろう「ぼく、そろばんやってるんで」\nゆうた「ぼくは暗算得意なんで」\n\n（2人とも、本気で速かった。候補生チーム、たじたじ）\n\nしんた「……うちの学校、レベル高いでしょ」",
  "（帰り際、生徒全員が寄せ書きをくれた）\n\n『デビューしたら、体育館でライブしてください』\n『わたしたちのこと、忘れないでください』\n『ぜったい、ぜったい、応援してます』\n\n（メンバー全員、しばらく寄せ書きから顔を上げられなかった）",
