function startRevenge(misses, done) {
  const list = misses.slice(0, 3);
  let i = 0;
  const next = () => {
    if (i >= list.length) return done();
    const m = list[i++];
    const lec = MATH.lecture(m.tag);
    const mid = MENTOR_G[m.genre] || "kanade";
    const ansTxt = `${MATH.ansText(m.a)}${m.a.unit || ""}`;
    showEvent({
      c: mid,
      t: `${pick(MENTOR_INTRO[mid])}\n\n📖【${lec.t}】\n${lec.b}\n\nさっきの問題の答えは「${ansTxt}」。\n……理解したら、同じ問題でリベンジだ。`,
      ch: [{ t: "🔥 もう一回、挑戦する", fx: {}, after: () => startQuiz({
        mode: "lesson", genre: m.genre || "pi", lv: 5, total: 1,
        fixed: [{ q: m.qq, a: m.a, tag: "リベンジ・" + m.tag, small: true, note: m.note, genre: m.genre, time: Math.round((m.time || 60) * 1.5) }],
        title: "📖 復習タイム・リベンジ",
        onEnd: r => {
          if (r.correct === 1) {
            if (G) {
              G.revengeOK = (G.revengeOK || 0) + 1;
              addStat("me", 2);
              const cm = CMDS.find(c => c.g === m.genre);
              if (cm) addStat(cm.main, 2);
              G.fans += 150; save();
            }
            confetti(26); sfx.clear();
            showEvent({ c: mid, t: `${pick(MENTOR_WIN[mid])}\n\n✨ リベンジ成功！ 特別ボーナス獲得\n精神力 +2${G ? `　／　リベンジ成功 累計${G.revengeOK}回` : ""}`,
              ch: [{ t: "▶", fx: {}, after: next }] });
          } else {
            showEvent({ c: mid, t: `${pick(MENTOR_LOSE[mid])}\nこの型は、いつか必ず本番でおまえを助ける。\n答えは「${ansTxt}」。今日はそれを覚えて帰ればいい」`,
              ch: [{ t: "▶", fx: {}, after: next }] });
          }
        }
      }) }]
    });
  };
  next();
}

/* ================= 結果パネル ================= */
function scoreRank(s) { return s >= 95 ? ["PERFECT", "#ffcf5c"] : s >= 85 ? ["EXCELLENT", "#ff9f43"] : s >= 70 ? ["GOOD", "#3ddc97"] : s >= 50 ? ["まずまず", "#4cc9f0"] : ["もう一度", "#7b7b95"]; }
function showResult(o) {
  const [rn, rc] = scoreRank(o.r.score);
  const miss = o.r.misses.slice(0, 5).map(m => `<div class="missRow"><span>${m.q}</span><em>${MATH.ansHtml(m.a)}</em></div>`).join("");
  $("resPanel").innerHTML = `
    <div class="resHead">
      <div class="lbl">${o.title}</div>
      <div class="resScore">${o.r.score}<small> 点</small></div>
      <div class="resRank" style="background:${rc}">${rn}</div>
      <div style="font-size:10.5px;color:var(--ink3);margin-top:8px">正解 ${o.r.correct}/${o.r.total}　最大コンボ ${o.r.best}　平均 ${o.r.avgTime}秒</div>
    </div>
    <div class="gains">${o.gains.map(g => `<div class="gain"><span>${g[0]}</span><b>+${g[1]}</b></div>`).join("")}
      ${o.fans ? `<div class="gain"><span>📈 注目度</span><b>+${o.fans.toLocaleString()}</b></div>` : ""}</div>
    ${o.extra || ""}
    ${miss ? `<div class="missBox"><div class="mt">✏️ MISSED</div>${miss}</div>` : `<div class="smallnote">ノーミス。文句なし。</div>`}
    ${o.r.misses.length ? `<button class="btn gold" id="revBtn" style="margin-bottom:8px">📖 復習タイム（解説→リベンジで特別ボーナス）</button>` : ""}
    <button class="btn" id="resOk">次へ</button>`;
  $("ovResult").classList.add("on");
  const rb = $("revBtn");
  if (rb) rb.onclick = () => { sfx.tap(); $("ovResult").classList.remove("on"); startRevenge(o.r.misses, o.after); };
  $("resOk").onclick = () => { sfx.tap(); $("ovResult").classList.remove("on"); o.after(); };
}

/* ================= スキル ================= */
function checkSkills(done) {
  const got = SKILLS.filter(s => !G.skills.includes(s.id) && s.chk(G));
  if (!got.length) return done();
  const s = got[0];
  G.skills.push(s.id);
  if (!DB.meta.skills.includes(s.id)) DB.meta.skills.push(s.id);
  sfx.skill();
  $("sfBox").innerHTML = `<div class="sfLabel">S K I L L　U N L O C K E D</div>
    <div class="sfStar">✨</div><div class="sfName">${s.e} ${s.n}</div><div class="sfDesc">${s.d}</div>`;
  $("skillFlash").classList.add("on");
  setTimeout(() => { $("skillFlash").classList.remove("on"); checkSkills(done); }, 2200);
}

/* ================= 1日の終わり ================= */
const FANMILES = [3000, 10000, 30000, 80000];
const FANMILE_EV = {
  3000:  { c: "haru",    t: "「ニュース！ おまえのファン、3000人こえたって！\n事務所の廊下に、ファンからの応援ボード飾られてたぞ！」" },
  10000: { c: "kanade",  t: "「注目度1万、おめでとう。\n……今日ね、街できみの名前を話してる学生を見かけたよ。\n『あの子、絶対デビューするよね』って」" },
  30000: { c: "riku",    t: "「3万人。……もう『無名の候補生』じゃないな。\n雑誌が特集を組みたいって言ってきてる。\nおまえの物語、みんなが見たがってるんだよ」" },
  80000: { c: "tsukasa", t: "「8万。……この数字の意味がわかるか。\nおまえはもう、デビュー前から『スター』だ。\nあとは、ステージがそれを証明するだけだ」" },
};
function endDay() {
  G.milesSeen = G.milesSeen || []; G.fanMilesSeen = G.fanMilesSeen || [];
  if (G.day === 22 && !G.concertDone) {
    G.concertDone = true; save();
    return startConcert(() => afterDay());
  }
  const fmile = FANMILES.find(m => G.fans >= m && !G.fanMilesSeen.includes(m));
  if (fmile) {
    G.fanMilesSeen.push(fmile); save();
    const ev = FANMILE_EV[fmile];
    return showEvent({ c: ev.c, t: `📣 注目度 ${fmile.toLocaleString()} とっぱ！\n\n${ev.t}`, ch: [{ t: "▶", fx: { fans: 500, cond: 1 }, after: () => endDay() }] });
  }
  const mile = MILES.find(m => G.totalQ >= m && !G.milesSeen.includes(m));
  if (mile) {
    G.milesSeen.push(mile); save();
    const ev = MILE_EV[mile];
    const evc = CANDS[ev.c] && !G.alive.includes(ev.c) ? "kanade" : ev.c;
    return showEvent({ c: evc, t: `🏅 通算${mile}問 とっぱ！\n\n${ev.t}`, ch: [{ t: "▶", fx: { st: { me: 3 }, cond: 1 }, after: () => endDay() }] });
  }
  /* シノ保証枠：4日以上あいたら必ずシノイベント（脱落後はLINEで続く） */
  if (G.day - (G.shinoLast || 0) >= 4 && G.day < TOTAL_D) {
    const sPool = EVENTS.filter(e => e.c === "shino" && !G.evseen.includes(e.id));
    if (sPool.length) {
      const e = pick(sPool);
      G.evseen.push(e.id);
      if (!DB.meta.evseen.includes(e.id)) DB.meta.evseen.push(e.id);
      G.shinoLast = G.day; save();
      const gone = !G.alive.includes("shino");
      const t = gone ? "（脱落したシノから、LINEが届いた）\n\n" + e.t : e.t;
      return showEvent({ c: e.c, t, ch: e.ch.map(c => ({ t: c.t, fx: c.fx, after: () => afterDay() })) });
    }
  }
  if (maybeSeiko()) return;
  if (!G.sushiDone && G.alive.includes("takuto") && G.day >= 5 && Math.random() < .4) {
    G.sushiDone = true; save();
    return startSushi(() => afterDay());
  }
  if (!G.saisonDone && G.day >= 10 && Math.random() < .4) {
    G.saisonDone = true; save();
    return startSaison(() => afterDay());
  }
  if (G.day >= 7 && G.day < TOTAL_D - 1 && (G.natsuLast === undefined || G.day - G.natsuLast >= 2) && Math.random() < .5) {
    return startTokkun(() => afterDay());
  }
  if (!G.liveDone && G.day >= 13 && G.day < TOTAL_D - 1 && Math.random() < .35) {
    G.liveDone = true; save();
    return startLive(() => afterDay());
  }
  if (G.day >= 8 && G.day < TOTAL_D - 1 && (G.qboxLast === undefined || G.day - G.qboxLast >= 6) && Math.random() < .3) {
    save();
    return startQBox(() => afterDay());
  }
  {
    const lastVisit = Math.max(G.hinoLast ?? -99, G.nichiLast ?? -99, G.sapixLast ?? -99);
    if (G.day >= 6 && G.day < TOTAL_D - 1 && G.day - lastVisit >= 4 && Math.random() < .45) {
      /* 学校・塾訪問をローテーション（日野学園→日能研→SAPIX→…） */
      const seq = [startHino, startNichinoken, startSapix];
      const cnt = G.visitCount || 0;
      G.visitCount = cnt + 1; save();
      return seq[cnt % 3](() => afterDay());
    }
  }
  for (const id of G.alive) {
    const b = (BONDS[id] || []).find(x => G.aff[id] >= x.at && !G.bonds.includes(id + x.at));
    if (b) { G.bonds.push(id + b.at); return showEvent({ c: id, t: b.t, ch: [{ t: "▶", fx: b.fx, after: () => afterDay() }] }); }
  }
  if ((G.voiceCount || 0) < 3 && G.day >= 4 && G.day < TOTAL_D
      && Math.random() < (G.day >= 24 && (G.voiceCount || 0) < 2 ? .5 : .15)) {
    DB.meta.voicesSeen = DB.meta.voicesSeen || [];
    let avail = JUKEN_VOICES.map((_, i) => i).filter(i => !DB.meta.voicesSeen.includes(i));
    if (!avail.length) { DB.meta.voicesSeen = []; avail = JUKEN_VOICES.map((_, i) => i); }
    const vi = pick(avail);
    DB.meta.voicesSeen.push(vi);
    G.voiceCount = (G.voiceCount || 0) + 1;
    const v = JUKEN_VOICES[vi];
    const vc = CANDS[v.c] && !G.alive.includes(v.c) ? "kanade" : v.c;
    return showEvent({ c: vc, t: v.t, ch: [
      { t: "💪 ……おれも、頑張る", fx: { st: { me: 4 } }, after: () => afterDay() },
      { t: "🌸 心に刻んだ", fx: { st: { me: 3 }, cond: 1 }, after: () => afterDay() },
    ] });
  }
  if (Math.random() < .52 && G.day < TOTAL_D) {
    const pool = EVENTS.filter(e => !G.evseen.includes(e.id) && (!CANDS[e.c] || G.alive.includes(e.c))
      && (!e.need || Object.entries(e.need).every(([k, v]) => (G.aff[k] || 0) >= v)));
    if (pool.length) {
      const weighted = pool.flatMap(e => MAIN_CAST.has(e.c) ? [e, e, e] : [e]);
      const e = pick(weighted);
      G.evseen.push(e.id);
      if (!DB.meta.evseen.includes(e.id)) DB.meta.evseen.push(e.id);
      if (e.c === "shino") G.shinoLast = G.day;
      return showEvent({ c: e.c, t: e.t, ch: e.ch.map(c => ({ t: c.t, fx: c.fx, after: () => afterDay() })) });
    }
  }
  afterDay();
}
function afterDay() {
  if (Math.random() < .5) {
    let d = Math.random() < .5 ? -1 : 1;
    if (G.stam < 30) d = -1;
    if (G.stam > 80 && Math.random() < .6) d = 1;
    G.cond = clamp(G.cond + d, 0, 4);
  }
  G.alive.forEach(id => { G.aff[id] = Math.max(0, G.aff[id] - .6); });
  G.day++;
  if (G.day > TOTAL_D) return ending("time");
  save();
  /* 合宿入り */
  if (G.day === CAMP[0] && !G.team) return campStart();
  /* 固有ストーリーイベント */
  G.fixedSeen = G.fixedSeen || [];
  const fev = FIXED[G.day];
  if (fev && !G.fixedSeen.includes(G.day)) {
    G.fixedSeen.push(G.day); save();
    if (fev.solo) return showSoloSelect();
    return showEvent({ c: fev.c, t: fev.t, ch: fev.ch.map(c => ({ t: c.t, fx: c.fx, after: () => renderMain() })) });
  }
  /* 審査当日の朝＝直前の追い込みイベント */
  const a = nextAud();
  if (a && a.d === G.day) return eveEvent(a);
  renderMain();
}

/* ================= 直前の追い込み（審査当日の朝） ================= */
function eveEvent(a) {
  const isFinal = a.d === TOTAL_D;
  const weak = pickWeak();
  const enjinAff = Object.fromEntries(G.alive.map(id => [id, 3]));
  const ch = [
    { t: `🔥 ギリギリまで追い込む（${STATS.find(s => s.k === weak).n}を仕上げる）`, fx: { st: { [weak]: 4 }, stam: -15 } },
    { t: "😴 体を整えて、いちばん良い状態で立つ", fx: { stam: 35, cond: 1 } },
    { t: "🤝 みんなで円陣を組む", fx: { st: { me: 4 }, aff: enjinAff, silent: true, msg: "円陣を組んだ。精神力 +4／全員の好感度 +3" } },
  ];
  if (isFinal) {
    const letters = {
      kai:  "カイ「おれの分まで、なんて言わない。おまえは、おまえの理由で立て」",
      sora: "ソラ「ぼくの推しは、{name}くんです。ずっとです」",
      haru: "ハル「あの舞台、おまえに似合うよ。……見に行くからな、最前列」",
      shion: "シオン「……言葉は苦手だから、ひとことだけ。……勝て」",
      ren:  "レン「おまえに負けたことだけが、いまだに悔しい。だから勝ち続けろ」",
      takuto: "タクト「約束の回転ずし、忘れてないよな。おれのおごりだ。……行ってこい」",
      hara: "ハラ「ちゃぼす！！ おれのトス、ちゃんと決めてこいよ！！」",
      noa:  "ノア「Slow and steady. ……でも今夜だけは、全速力でいけ」",
      roi:  "ロイ「本番の衣装、袖のボタン留めとけよ。細部だぞ、細部。……頼んだ」",
      masaki: "マサキ「君の努力は僕が保証する。だから最後まで、胸を張って」",
      shuto: "シュウト「でっかい笑顔！ 約束だからな！！」",
      shino: "シノ「……積み上げた数は、裏切らない。……きみがいちばん積んだ」",
      daigo: "ダイゴ「兄ちゃんの分まで頼んだで！ 声、いちばんデカく出せや！！」",
      yuma: "ユウマ「カウントは体に入ってる。あとは楽しむだけだ。……いけ」",
    };
    const dropped = CAND_IDS.filter(id => !G.alive.includes(id));
    const lt = dropped.map(id => letters[id]).filter(Boolean).join("\n");
    return showEvent({
      c: "kanade",
      t: `「いよいよ、今夜で全部決まる。\n……その前に。これ、預かってたんだ」\n\n（脱落していったメンバーからの手紙だった）\n\n${lt || "……"}\n\n「さあ。最後の時間、どう使う？」`,
      ch: ch.map(c => ({ ...c, after: () => renderMain() }))
    });
  }
  showEvent({
    c: "kanade",
    t: `「今日は『${a.n}』。\n……ここまでやってきたことは、消えない。\n\n本番まで、あと少し。どう過ごす？」`,
    ch: ch.map(c => ({ ...c, after: () => renderMain() }))
  });
}

/* ================= ソロ構成選び（DAY20） ================= */
function showSoloSelect() {
  renderMain();
  openSheet(`<div class="ptitle">個人パフォーマンスの構成<small>4次審査は完全ソロ。自分をどう魅せる？</small></div>
  <div class="list">${SOLOS.map(s => `<button class="item" data-s="${s.id}">
    <span class="ie">${s.e}</span><div class="it"><b>${s.n}</b>
    <small>${s.d}（${STATS.find(x => x.k === s.k).n}が審査に上乗せ）</small></div></button>`).join("")}</div>
  <div class="smallnote">いまの自分のステータスと相談して決めよう。</div>`);
  $("sheetPanel").querySelectorAll(".item").forEach(b => b.onclick = () => {
    G.solo = b.dataset.s; sfx.clear(); save(); closeSheet();
    const s = SOLOS.find(x => x.id === G.solo);
    showEvent({
      c: "shion",
      t: `（構成表を見せると、シオンが静かにうなずいた）\n\n「……${s.n.replace(/で.*$/, "")}。\nおまえらしい。\n\n……本番、いちばん近くで見てる」`,
      ch: [{ t: "「ああ。見てて」", fx: { aff: { shion: 6 }, st: { me: 3 } }, after: () => renderMain() }]
    });
  });
}

/* ================= 合宿 ================= */
function campStart() {
  showEvent({
    c: "tsukasa",
    t: "「今日から6日間、強化合宿だ。\n3次審査の課題はチーム対抗の課題曲。\n\n……チームは、おまえたちで決めろ。\nその選択も、審査の対象だ」",
    ch: [{ t: "チームを組む", fx: {}, after: () => pickTeam() }]
  });
}
function pickTeam() {
  const sel = [];
  const render = () => {
    openSheet(`<div class="ptitle">チームを組む<small>2人えらぶ。好感度が高いほどチーム力が上がる</small></div>
    <div class="list">${G.alive.map(id => {
      const c = CANDS[id], on = sel.includes(id);
      return `<button class="item" data-c="${id}" style="${on ? "box-shadow:0 0 0 1.5px var(--gold) inset" : ""}">
        <img class="ii" src="${c.img}" alt=""><div class="it"><b>${on ? "◆ " : ""}${c.n}</b>
        <small>${c.role}　好感度 ${Math.round(G.aff[id])}</small></div></button>`;
    }).join("")}</div>
    <div style="height:12px"></div>
    <button class="btn" id="teamOk" ${sel.length === 2 ? "" : "disabled"}>このチームで行く</button>`);
    $("sheetPanel").querySelectorAll(".item").forEach(b => b.onclick = () => {
      const id = b.dataset.c;
      if (sel.includes(id)) sel.splice(sel.indexOf(id), 1);
      else if (sel.length < 2) sel.push(id);
      sfx.tap(); render();
    });
    const ok = $("teamOk");
    if (ok) ok.onclick = () => {
      G.team = [...sel]; closeSheet(); sfx.clear(); save();
      showEvent({
        c: sel[0],
        t: `（${CANDS[sel[0]].n}と${CANDS[sel[1]].n}とチームを組んだ）\n\n「……よろしく。\n6日で、仕上げる」`,
        ch: [{ t: "▶", fx: { aff: { [sel[0]]: 5, [sel[1]]: 5 }, silent: true }, after: () => pickLeader() }]
      });
    };
  };
  render();
}
/* リーダー決め */
function pickLeader() {
  const [a, b] = G.team;
  showEvent({
    c: b,
    t: "「……で。このチーム、リーダーは誰がやる？」\n\n（3人の視線が交差する。誰が背負うかで、チームの形が決まる）",
    ch: [
      { t: "「おれがやる」", fx: { st: { me: 5, tk: 3 }, msg: "リーダーになった。責任と引きかえに、心が据わった" },
        after: () => { G.leader = "me"; save(); pickSong(); } },
      { t: `「${CANDS[a].n}に任せたい」`, fx: { aff: { [a]: 9 }, st: { me: 2 } },
        after: () => { G.leader = a; save(); pickSong(); } },
      { t: `「${CANDS[b].n}がいいと思う」`, fx: { aff: { [b]: 9 }, st: { me: 2 } },
        after: () => { G.leader = b; save(); pickSong(); } },
    ]
  });
}
/* 課題曲選び */
function pickSong() {
  openSheet(`<div class="ptitle">チーム課題曲を選ぶ<small>3次審査で披露する1曲。曲で勝負どころが変わる</small></div>
  <div class="list">${SONGS.map(s => `<button class="item" data-s="${s.id}">
    <span class="ie">${s.e}</span><div class="it"><b>『${s.n}』</b>
    <small>${s.d}（いまの${STATS.find(x => x.k === s.k).n} ${Math.round(G.st[s.k])}）</small></div></button>`).join("")}</div>
  <div class="smallnote">選んだ曲に合うステータスが高いほど、3次審査の点数が上がる。</div>`);
  $("sheetPanel").querySelectorAll(".item").forEach(btn => btn.onclick = () => {
    G.song = btn.dataset.s; sfx.clear(); save(); closeSheet();
    const s = SONGS.find(x => x.id === G.song);
    const ldr = G.leader === "me" ? "きみ" : CANDS[G.leader].n;
    showEvent({
      c: G.team[0],
      t: `課題曲は『${s.n}』。リーダーは${ldr}。\n\n「……決まりだな。\n6日後、いちばんいいステージにする」\n\n（合宿が、始まった）`,
      ch: [{ t: "「やろう」", fx: { cond: 1 }, after: () => renderMain() }]
    });
  });
}

/* ================= イベント ================= */
function showEvent(e) {
  const p = PERSON(e.c);
  if (G && !G.done) renderMain();
  $("evPanel").innerHTML = `
    <div class="evTop"><img src="${p.img}" alt=""><div class="evName">${p.n}</div></div>
    <div class="evBody">${e.scene ? `<img src="${e.scene}" style="width:100%;border-radius:12px;margin-bottom:10px;display:block">` : ""}${rep(e.t).replace(/\n/g, "<br>")}</div>
    <div class="evChoices">${e.ch.map((ch, i) => `<button class="evc" data-i="${i}">${rep(ch.t)}</button>`).join("")}</div>`;
  $("ovEvent").classList.add("on");
  $("evPanel").querySelectorAll(".evc").forEach(b => b.onclick = () => {
    sfx.tap();
    const ch = e.ch[+b.dataset.i];
    $("ovEvent").classList.remove("on");
    applyFx(ch.fx || {});
    if (ch.after) ch.after(); else renderMain();
  });
}
function applyFx(f) {
  const msgs = [];
  if (f.stam) { G.stam = clamp(G.stam + f.stam, 0, G.maxStam); msgs.push(`体力 ${f.stam > 0 ? "+" : ""}${f.stam}`); }
  if (f.fans) { G.fans += f.fans; msgs.push(`📈 注目度 +${f.fans.toLocaleString()}`); }
  if (f.cond) { G.cond = clamp(G.cond + f.cond, 0, 4); msgs.push(`調子 ${f.cond > 0 ? "アップ" : "ダウン"}`); }
  if (f.st) for (const k in f.st) { const d = addStat(k, f.st[k]); if (d) msgs.push(`${STATS.find(s => s.k === k).n} +${d}`); }
  if (f.aff) for (const k in f.aff) {
    if (!CANDS[k]) continue;                      /* 審査員など好感度を持たない相手は無視 */
    G.aff[k] = clamp((G.aff[k] || 0) + f.aff[k], 0, 100);
    if (!f.silent && f.aff[k]) msgs.push(`${CANDS[k].n} 好感度 ${f.aff[k] > 0 ? "+" : ""}${f.aff[k]}`);
  }
  if (f.msg) toast(f.msg);
  if (msgs.length && !f.silent) toast(msgs.join("　"));
  save();
}

/* ================= クイズ・エンジン ================= */
let Q = null;
function startQuiz(cfg) {
  const fx = skillFx();
  Q = {
    ...cfg, idx: 0, correct: 0, combo: 0, best: 0, sum: 0, misses: [], times: [],
    input: "", shield: fx.shield, lock: false, t0: 0, limit: 10, raf: 0, startAll: performance.now(),
    timeMul: 1 + (G && G.items.note ? .3 : 0) + (cfg.mode === "drill" ? .5 : 0), lastQ: "",
  };
  $("scrQuiz").classList.toggle("stage", cfg.mode === "aud");
  $("qGenre").textContent = cfg.title;
  $("qTotal").textContent = cfg.total;
  $("qJudges").classList.toggle("hide", cfg.mode !== "aud");
  if (cfg.mode === "aud") renderJudges(0);
  buildPad();
  show("scrQuiz");
  nextQ();
}
function buildPad() {
  const keys = ["7", "8", "9", "back", "4", "5", "6", "/", "1", "2", "3", ".", "0", "clear", "ok"];
  $("pad").innerHTML = keys.map(k => {
    if (k === "back") return `<button class="key fn" data-k="back">⌫</button>`;
    if (k === "clear") return `<button class="key fn" data-k="clear">CL</button>`;
    if (k === "ok") return `<button class="key ok w2" data-k="ok">解答</button>`;
    if (k === "/") return `<button class="key fn" data-k="/">a/b</button>`;
    return `<button class="key" data-k="${k}">${k}</button>`;
  }).join("");
  $("pad").querySelectorAll(".key").forEach(b => b.onclick = () => keyIn(b.dataset.k));
}
function keyIn(k) {
  if (!Q || Q.lock) return;
  sfx.tap();
  if (k === "back") Q.input = Q.input.slice(0, -1);
  else if (k === "clear") Q.input = "";
  else if (k === "ok") return submit();
  else if (Q.input.length < 10) {
    if (k === "." && (Q.input.includes(".") || !Q.input)) return;
    if (k === "/" && (Q.input.includes("/") || !Q.input)) return;
    Q.input += k;
  }
  drawInput();
}
function drawInput() { $("qVal").textContent = Q.input; $("qInput").className = ""; }
function nextQ() {
  if (Q.idx >= Q.total) return endQuiz();
  let q;
  if (Q.fixed) { q = Q.fixed[Q.idx]; }
  else {
    let tries = 0;
    do { q = MATH.gen(Q.mode === "aud" ? pick(Q.lv >= 4 ? ["pi", "frac", "ratio", "gyaku", "kufuu", "bun", "bun"] : ["pi", "frac", "ratio", "gyaku", "kufuu"]) : Q.genre, Q.lv); tries++; }
    while (q.q === Q.lastQ && tries < 8);
  }
  Q.lastQ = q.q; Q.cur = q; Q.input = "";
  $("qNo").textContent = Q.idx + 1;
  $("qTag").textContent = q.tag;
  $("qText").innerHTML = q.q;
  $("qText").className = q.small ? "small" : "";
  $("qNote").textContent = q.note || "";
  $("qUnit").textContent = q.a.unit || "";
  $("qCombo").textContent = Q.combo >= 2 ? `${Q.combo} COMBO` : "";
  drawInput();
  Q.limit = q.time * Q.timeMul;
  Q.t0 = performance.now(); Q.lock = false;
  cancelAnimationFrame(Q.raf); tickQ();
}
function tickQ() {
  if (!Q || Q.lock) return;
  const el = (performance.now() - Q.t0) / 1000;
  const left = Math.max(0, 1 - el / Q.limit);
  const bar = $("qTimer");
  bar.style.width = (left * 100) + "%";
  bar.classList.toggle("warn", left < .15);
  if (left <= 0) return judge(false, true);
  Q.raf = requestAnimationFrame(tickQ);
}
function submit() { if (!Q.input) return; judge(MATH.check(Q.input, Q.cur.a), false); }
function judge(ok, timeout) {
  if (Q.lock) return;
  Q.lock = true; cancelAnimationFrame(Q.raf);
  const el = (performance.now() - Q.t0) / 1000;
  Q.times.push(Math.min(el, Q.limit));
  let sc = 0, label = "", color = "#ffcf5c";
  if (ok) {
    Q.correct++;
    const r = el / Q.limit;
    if (r <= .3) { sc = 100; label = "PERFECT!"; color = "#ffcf5c"; sfx.great(); }
    else if (r <= .55) { sc = 88; label = "GREAT!"; color = "#ff9f43"; sfx.good(); }
    else if (r <= .8) { sc = 74; label = "GOOD!"; color = "#3ddc97"; sfx.good(); }
    else { sc = 58; label = "OK"; color = "#4cc9f0"; sfx.good(); }
    Q.combo++; Q.best = Math.max(Q.best, Q.combo);
    if (Q.combo >= 3) sc = Math.min(100, sc + Math.min(10, Q.combo));
    $("qInput").className = "ok";
  } else {
    if (Q.shield > 0) { Q.shield--; label = "SAVE!"; color = "#8b7bff"; }
    else { Q.combo = 0; label = timeout ? "TIME UP…おしい！" : "MISS"; color = "#e63946"; }
    sfx.bad();
    Q.misses.push({ q: Q.cur.q.replace(/<br>/g, " "), qq: Q.cur.q, a: Q.cur.a, tag: Q.cur.tag, genre: Q.cur.genre, time: Q.cur.time, note: Q.cur.note, small: Q.cur.small });
    $("qInput").className = "ng";
  }
  Q.sum += sc;
  let sub = ok ? "" : `<small>正解　${MATH.ansHtml(Q.cur.a)}${Q.cur.a.unit || ""}</small>`;
  if (ok && Q.combo >= 3 && Math.random() < .45) sub = `<small>${cheerLine()}</small>`;
  $("qCombo").textContent = Q.combo >= 2 ? `${Q.combo} COMBO` : "";
  $("qCombo").className = Q.combo >= 3 ? "hot" : "";
  $("qFb").innerHTML = `<div class="fbi" style="color:${color}">${label}${sub}</div>`;
  $("qFb").classList.add("on");
  if (Q.mode === "aud") renderJudges(Q.sum / Math.max(1, Q.idx + 1));
  Q.idx++;
  setTimeout(() => { $("qFb").classList.remove("on"); nextQ(); }, ok ? (sub ? 1100 : 600) : 1500);
}
function endQuiz() {
  cancelAnimationFrame(Q.raf);
  const score = Math.round(Q.sum / Q.total);
  const avgTime = Math.round(Q.times.reduce((a, b) => a + b, 0) / Q.total * 10) / 10;
  const totalTime = Math.round((performance.now() - Q.startAll) / 100) / 10;
  const r = { score, correct: Q.correct, total: Q.total, best: Q.best, misses: Q.misses, avgTime, totalTime };
  const cb = Q.onEnd; Q = null; cb(r);
}
document.addEventListener("keydown", ev => {
  if (!Q || !$("scrQuiz").classList.contains("on")) return;
  const k = ev.key;
  if (/^[0-9]$/.test(k)) keyIn(k);
  else if (k === ".") keyIn(".");
  else if (k === "/") keyIn("/");
  else if (k === "Backspace") { ev.preventDefault(); keyIn("back"); }
  else if (k === "Enter") keyIn("ok");
});

/* ================= 審査 ================= */
function renderJudges(avg) {
  $("qJudges").innerHTML = JUDGES.map((j, i) => {
    const v = clamp(avg - i * 3 + 6, 0, 100);
    return `<div class="jd ${v > 62 ? "good" : ""}"><img src="${j.img}" alt="${j.n}">
      <div class="jn">${j.n}</div><div class="jb"><u style="width:${v}%"></u></div></div>`;
  }).join("");
}
function startAudition() {
  const a = nextAud(), idx = AUDS.indexOf(a);
  const rivalLine = idx === 4
    ? { c: "shino", t: "「……ここまで来たね。\n\n……最後だから、言う。\nきみと出会えて、よかった。\n\n……本気で来て。\n……ぼくも、ぜんぶ出すから」" }
    : G.alive.includes("hara")
    ? { c: "hara", t: "「ちゃぼすーー！！ 本番だな！！\n\n緊張してるか？ よし、深呼吸！ すって〜、はいて〜！\n\n……行ってこい！ おまえの全力、見せてやれ！！」" }
    : { c: "takuto", t: "「本番だな。……大丈夫、いつも通りでいい。\nおまえの努力は、おれがいちばん知ってる。\n\n行ってこい」" };
  const goQuiz = () => startQuiz({
    mode: "aud", lv: a.lv, total: a.q, title: `🎬 ${a.n}`,
    onEnd: r => finishAudition(a, idx, r)
  });
  showEvent({
    c: rivalLine.c, t: rivalLine.t,
    ch: [{ t: "ステージへ", fx: {}, after: () => showEvent({
      c: "kanade",
      t: `（ステージ袖。ソウ先輩が肩に手を置いた）

「本番前の儀式、教えたよね。
【自己宣言】——自分に、勝利の言葉をかけてあげて。

脳は、最後に聞いた言葉を信じて動くから。
……さあ、どうぞ」`,
      ch: [
        { t: `🔥 「${G.totalQ > 0 ? `おれは${G.totalQ}問解いてきた。` : ""}やれる。やってきたから」`, fx: { st: { me: 5 } }, after: goQuiz },
        { t: "💫 「今日の自分が、いちばん強い」", fx: { st: { me: 4 }, cond: 1 }, after: goQuiz },
        { t: "🌸 「楽しむ。ぜんぶ出しきる」", fx: { st: { ex: 3, me: 3 } }, after: goQuiz },
      ]
    }) }]
  });
}
function judgeScore(j, quiz, fx) {
  let statPart = 0;
  for (const k in j.w) statPart += G.st[k] * j.w[k];
  if (!fx.iron) statPart *= (1 - clamp((60 - G.st.me) / 100, 0, .25));
  const outfitB = G.outfit ? OUTFITS.find(o => o.id === G.outfit).ex * .15 : 0;
  return Math.round(statPart * .6 + quiz * .4 + fx.aud + outfitB);
}
function finishAudition(a, idx, r) {
  const fx = skillFx();
  const each = JUDGES.map(j => ({ j, s: judgeScore(j, r.score, fx) }));
  const total = Math.round(each.reduce((s, e) => s + e.s, 0) / 3);
  /* チームボーナス（3次審査） */
  let teamB = 0, songB = 0, leadB = 0, soloB = 0;
  let songName = "", soloName = "";
  if (idx === 2 && G.team) {
    teamB = Math.round(G.team.reduce((s, i) => s + G.aff[i], 0) / 20);
    if (G.song) {
      const sg = SONGS.find(x => x.id === G.song);
      songB = clamp(Math.round((G.st[sg.k] - 50) * .15), 0, 8);
      songName = sg.n;
    }
    if (G.leader === "me") leadB = 3;
    each.forEach(e => e.s += teamB + songB + leadB);
  }
  /* ソロ構成ボーナス（4次審査） */
  if (idx === 3 && G.solo) {
    const sl = SOLOS.find(x => x.id === G.solo);
    soloB = clamp(Math.round((G.st[sl.k] - 50) * .15), 0, 8);
    soloName = sl.n;
    each.forEach(e => e.s += soloB);
  }
  const finalTotal = total + teamB + songB + leadB + soloB;
  /* 段階通過：期待枠 → 合格 → トップ通過 */
  const hope = a.need - 16, top = a.need + 8;
  const tier = finalTotal >= top ? 2 : finalTotal >= a.need ? 1 : finalTotal >= hope ? 0 : -1;
  const pass = tier >= 0;

  /* ライバルのスコア（周回ごとの才能ロール＋ゆらぎで毎回順位が変わる） */
  const rivals = G.alive
    .map(id => ({ id, n: CANDS[id].n, img: CANDS[id].img,
      s: (a.base[id] ?? a.need - 2) + ((G.talent && G.talent[id]) || 0) + ri(-6, 6) }));
  const board = [...rivals, { id: "me", n: G.name, img: AVATARS[G.av].img, s: finalTotal, me: true }]
    .sort((x, y) => y.s - x.s);
  const myRank = board.findIndex(b => b.me) + 1;

  G.totalQ += r.total; G.totalOK += r.correct;
  G.bestCombo = Math.max(G.bestCombo, r.best);
  const fanMul = tier === 2 ? 1.5 : tier === 1 ? 1 : tier === 0 ? .65 : .3;
  const fans = Math.round(1200 * fanMul * (1 + idx * .6) * (1 + Math.max(0, finalTotal - hope) / 100) * (1 + fx.fan));
  G.fans += Math.max(0, fans);
  G.auds.push({ n: a.n, score: finalTotal, rank: myRank, pass, tier });
  G.lastRank = myRank; G.lastRankOf = board.length;

  if (tier === 2) { confetti(60); sfx.clear(); } else if (pass) { confetti(30); sfx.clear(); } else sfx.bad();

  const cmt = e => pick((JCOMMENT[e.j.id].find(c => e.s >= c[0]) || JCOMMENT[e.j.id][3])[1]);
  $("resPanel").innerHTML = `
    <div class="resHead">
      <div class="lbl">${a.n}　／　${a.sub}</div>
      <div class="resScore">${finalTotal}<small> 点</small></div>
      <div class="resRank" style="background:${tier === 2 ? "#ffcf5c" : tier === 1 ? "#ff9f43" : tier === 0 ? "#3ddc97" : "#e63946"};color:#08080d">${tier === 2 ? "🏆 トップ通過" : tier === 1 ? "合格ライン突破" : tier === 0 ? "✨ 期待枠で通過" : "期待枠ライン " + hope + "点に届かず"}</div>
      <div style="font-size:11px;color:var(--ink3);margin-top:8px">この審査の順位　<b style="color:var(--gold);font-size:17px">${myRank}位</b> / ${board.length}人</div>
    </div>
    ${each.map(e => `<div class="judgeRow"><img src="${e.j.img}" alt="">
      <div class="jt"><b>${e.j.n}（${e.j.role}）</b><small>${cmt(e)}</small></div>
      <div class="js" style="color:${e.s >= 75 ? "#ffcf5c" : e.s >= 60 ? "#3ddc97" : "#e63946"}">${e.s}</div></div>`).join("")}
    <div class="gains" style="margin-top:10px">
      ${teamB ? `<div class="gain"><span>チームボーナス（${G.team.map(i => CANDS[i].n).join("・")}）</span><b>+${teamB}</b></div>` : ""}
      ${songB ? `<div class="gain"><span>課題曲『${songName}』ボーナス</span><b>+${songB}</b></div>` : ""}
      ${leadB ? `<div class="gain"><span>リーダーとしてチームを牽引</span><b>+${leadB}</b></div>` : ""}
      ${soloB ? `<div class="gain"><span>ソロ構成「${soloName}」ボーナス</span><b>+${soloB}</b></div>` : ""}
      <div class="gain"><span>計算パフォーマンス</span><b>${r.score}点 → 各審査員に40%反映</b></div>
      <div class="gain"><span>📈 注目度</span><b>+${Math.max(0, fans).toLocaleString()}</b></div>
    </div>
    <div class="missBox"><div class="mt">RANKING</div>
      ${board.map((b, i) => `<div class="missRow" style="${b.me ? "color:var(--gold)" : ""}">
        <span>${i + 1}位　${esc(b.n)}${b.me ? "（きみ）" : ""}</span><em>${b.s}</em></div>`).join("")}</div>
    <div class="smallnote">🏆 トップ通過 ${top}点〜　／　合格 ${a.need}点〜　／　✨ 期待枠 ${hope}点〜<br>正解 ${r.correct}/${r.total}　最大コンボ ${r.best}</div>
    <button class="btn" id="resOk">合格者発表へ</button>`;
  $("ovResult").classList.add("on");
  $("resOk").onclick = () => {
    sfx.tap(); $("ovResult").classList.remove("on");
    checkSkills(() => announce(a, idx, board, pass, tier));
  };
}

/* ================= 合格者発表 ================= */
function announce(a, idx, board, pass, tier) {
  const isFinal = idx === 4;
  /* 脱落者＝その審査で下位に沈んだライバル（毎回変わる）。シノは序盤（1次・2次）は脱落しない */
  const drops = isFinal ? [] :
    [...board].filter(b => !b.me && !(b.id === "shino" && idx < 2)).sort((x, y) => x.s - y.s).slice(0, a.dropN || 0).map(b => b.id);
  show("scrAnn");
  $("annTitle").textContent = isFinal ? "最 終 結 果 発 表" : "合 格 者 発 表";
  $("annSub").innerHTML = "";
  $("annList").innerHTML = "";
  $("annBtn").classList.add("hide");

  const lines = isFinal
    ? ["「これより、最終結果を発表する」", "「デビューするのは、5人」", "「……名前を呼ばれた者だけが、ステージに立てる」"]
    : ["「これより、合格者を発表する」", "「呼ばれなかった者は、ここで終わりだ」"];

  let li = 0;
  const step = () => {
    if (li < lines.length) {
      $("annSub").innerHTML = lines[li];
      sfx.drum(); li++;
      return setTimeout(step, 1400);
    }
    revealRows();
  };
  setTimeout(step, 500);

  function revealRows() {
    /* 発表順：下位から呼ぶ（緊張感） */
    let order, passIds;
    if (isFinal) {
      passIds = board.slice(0, 5).map(b => b.id);
    } else {
      passIds = board.map(b => b.id).filter(id => !drops.includes(id));
    }
    order = [...board].reverse();
    $("annSub").innerHTML = isFinal ? "「デビューは、この5人だ」" : "";
    let i = 0;
    const next = () => {
      if (i >= order.length) return finish();
      const b = order[i];
      const ok = passIds.includes(b.id);
      let label = ok ? (isFinal ? "デビュー" : "合格") : "脱落";
      let cls = ok ? "pass " : "out ";
      if (b.me && !isFinal) {
        if (tier === 2) label = "トップ通過";
        else if (tier === 0) label = "期待枠";
        else if (!pass) {
          /* 期待枠ラインにも届かなかった本人 */
          if (G.warn) { label = "脱落"; cls = "out "; }
          else { label = "崖っぷち"; cls = ""; }
        }
      }
      const row = document.createElement("div");
      row.className = "annRow in " + cls + (b.me ? "me" : "");
      row.innerHTML = `<img src="${b.img}" alt=""><div class="an">${esc(b.n)}${b.me ? "（きみ）" : ""}</div>
        <div class="ax" style="${label === "崖っぷち" ? "color:#e63946" : ""}">${label}</div>`;
      $("annList").appendChild(row);
      row.scrollIntoView({ behavior: "smooth", block: "nearest" });
      if (ok) sfx.good(); else sfx.bad();
      i++; setTimeout(next, 900);
    };
    setTimeout(next, 700);

    function finish() {
      $("annBtn").classList.remove("hide");
      $("annBtn").textContent = "▶";
      setTimeout(() => $("annBtn").scrollIntoView({ behavior: "smooth", block: "center" }), 120);
      $("annBtn").onclick = () => {
        sfx.tap();
        if (isFinal) {
          const myRank = board.findIndex(b => b.me) + 1;
          if (myRank >= 6 && !G.extraTried) return extraSlot(board);
          return ending("final", board);
        }
        if (idx >= 2) G.team = null;   /* 合宿チームは3次審査で解散 */
        /* 崖っぷち判定 */
        if (!pass) {
          G.warnCount++;
          if (G.warn) return revivalExam();
          G.warn = true;
          toast("⚠ 崖っぷち：次の審査で挽回できなければ脱落");
        } else { G.warn = false; }
        if (drops.length) {
          const doDrop = k => {
            if (k >= drops.length) return afterDay();
            const d = drops[k];
            G.alive = G.alive.filter(x => x !== d);
            /* 脱落ドラマをランダム抽選（1周内で同じ展開は出ない） */
            const cand = EXIT_STORIES.filter(x => !(G.usedExits || []).includes(x.id));
            const story = pick(cand.length ? cand : EXIT_STORIES);
            G.usedExits = (G.usedExits || []).concat(story.id);
            const txt = story.t(CANDS[d].n, G.name) || dropLine(d);
            showEvent({ c: d, t: txt, ch: [{ t: "▶", fx: dropFx(d), after: () => doDrop(k + 1) }] });
          };
          return doDrop(0);
        }
        afterDay();
      };
    }
  }
}
/* ================= 脱落ドラマ（ランダム） ================= */
/* cn=去る候補生の名前, pn=プレイヤー名。tone: sad/shock/laugh/hope */
const EXIT_STORIES = [
  { id: "x_classic", tone: "sad", t: (cn, pn) => null },  /* キャラ固有の別れ（dropLine） */
  { id: "x_poach", tone: "shock", t: (cn, pn) => `（翌朝、${cn}の姿が宿舎になかった）\n\nソウ「……夜のうちに、話があったんだ。\n海外の大手事務所から、直接オファーが来た。\n\n『うちのグループで、すぐデビューしないか』って」\n\n置き手紙には、こうあった。\n『ごめん。おれは、おれの近道を行く。\n──でも${pn}、本物になるのは、遠回りしたやつだと思う』` },
  { id: "x_quit", tone: "shock", t: (cn, pn) => `${cn}「……オーディション、やめることにした。\n\n理由は……言わない。言えない。\n\nただ、ひとつだけ。\nアイドルになりたい理由が『逃げ』だって、ここで気づいたんだ。\n気づかせてくれたのは、本気のおまえらだよ。\n\n……今度は、ちゃんと向き合ってから戻ってくる」` },
  { id: "x_comedy", tone: "laugh", t: (cn, pn) => `${cn}「実は……お笑いの養成所に受かった。\n\nいや、笑うなよ！ ……いや、笑ってくれ！\n\nここでみんなを笑わせるたびに思ったんだ。\n歌より、ダンスより、笑い取ったときが一番きもちいいって。\n\n${pn}、おれが賞レース優勝するのと、おまえのデビュー、どっちが先か勝負な！」` },
  { id: "x_family", tone: "sad", t: (cn, pn) => `${cn}「……親父が倒れた。\n\n家の店、おれしか継げるやつがいない。\n\n夢と家族、天秤にかけたら……\n……いや、違うな。天秤なんかじゃない。\n両方大事だから、順番を決めただけだ。\n\n${pn}、テレビで待ってる。うちの店のテレビ、でかいんだ」` },
  { id: "x_abroad", tone: "hope", t: (cn, pn) => `${cn}「留学することにした。ダンスの本場に。\n\nこのオーディションで分かったんだ。\nおれの実力、まだ全然足りない。\n\n悔しいから、世界で修行してくる。\n${pn}、次に会うときは、おれがおまえのバックで踊ってるかもな。\n……いや、センターは譲らねえか」` },
  { id: "x_injury", tone: "sad", t: (cn, pn) => `（医務室のベッドで、${cn}は笑っていた）\n\n「膝、やっちゃった。全治3ヶ月。\n\n……踊れないアイドル候補生に、席はないよ。\nそれがこの世界のルール。分かってたことだ。\n\nでもさ、${pn}。\n治ったら、一番前で応援しに行くよ。\nペンライト、何色がいい？」` },
  { id: "x_actor", tone: "hope", t: (cn, pn) => `${cn}「映画のオーディションに受かった。\n\n……主演じゃないよ？ セリフも3つだけ。\nでも、審査の途中で気づいたんだ。\n\nおれ、歌ってるときより、\n『誰かを演じてるとき』のほうが自由なんだって。\n\n${pn}、いつかおまえの主演MVに、おれが出る。約束だ」` },
  { id: "x_solo", tone: "shock", t: (cn, pn) => `フマ「……${cn}については、おれから話す。\n\n事務所の判断で、ソロ・アーティストとして育成することになった。\nグループには入らない。だから、ここからは去る。\n\n……ライバルが1人、別の道で増えたと思え。\nそういう世界だ」` },
  { id: "x_study", tone: "sad", t: (cn, pn) => `${cn}「……受験、するって決めた。\n\n夢を諦めるんじゃない。順番を変えるだけ。\n勉強も、ダンスと同じで、逃げたら一生追いかけてくるから。\n\n${pn}、おまえ計算つよいじゃん。\n……ちょっとだけ、うらやましかったんだぜ。\n\n合格発表の日、おたがい笑ってような」` },
  { id: "x_band", tone: "laugh", t: (cn, pn) => `${cn}「バンド組むことにした。\n\nアイドルの曲って、誰かが作った曲だろ？\nおれ、自分の曲が歌いたくなっちゃったんだよね。\n\nギターは先週買った。コードは3つ弾ける。\n……3つありゃ、ロックはできる！\n\n${pn}、武道館で対バンしようぜ！」` },
  { id: "x_backdancer", tone: "hope", t: (cn, pn) => `${cn}「プロのバックダンサーにスカウトされた。\n\n……センターを取る夢は、いったん置いてく。\nでも、ステージに立つ夢は、諦めてない。\n\n有名アーティストのツアーで、日本中まわる。\n${pn}のツアーにも、いつか呼ばれてやるよ。\n……ギャラは高いぜ？」` },
  { id: "x_teacher", tone: "hope", t: (cn, pn) => `${cn}「地元でダンススクールの先生になる。\n\n笑うかもしれないけどさ、\nここで子どもたちのレッスン映像を見たとき、\n『教えたい』って気持ちが止まらなくなったんだ。\n\n10年後、おれの生徒がこのオーディションに来る。\nそのとき${pn}が審査員だったら……最高だな」` },
  { id: "x_rival_group", tone: "shock", t: (cn, pn) => `（発表の夜、${cn}が全員を集めた）\n\n「ライバル事務所のグループに、加入が決まった。\n\n……裏切り者って言われても、しかたない。\nでも、おれはステージに立つことを最優先した。\n\n${pn}。次に会うのは、音楽番組の楽屋か、賞レースの舞台だ。\n……負けねえからな。おまえも来いよ、そこまで」` },
  { id: "x_illness_family", tone: "sad", t: (cn, pn) => `${cn}「……妹が、入院してさ。\n\n手術、うまくいったんだけど、\nそばにいてやりたいって思ったら、涙が止まらなくなった。\n\n妹はさ、『お兄ちゃん、続けてよ』って怒るんだ。\nでも、いいんだ。\n\n${pn}、妹がおまえのファンになった。サインくれよ。\n……初めてのサイン、うちの妹でいいだろ？」` },
];

function dropLine(id) {
  const t = {
    kai: "「……21歳。ここが限界だった。\n\nでもな、{name}。おれの分まで行けなんて言わない。\nおまえは、おまえの理由で行け。\n\n……見てるから」",
    sora: "「くやしいです。ほんとに、くやしいです。\n\nでも、ぼく15歳なので。\n来年も、再来年も受けます。\n\n{name}くん、その時は先輩でいてください」",
    haru: "「あーあ、終わっちゃった。\n……ごめん、ちょっとだけ泣かせて。\n\nおれの分の空気、持っていけよ。\n{name}なら、あの舞台、似合うから」",
    hara: "「……ちゃぼすぅぅ……（号泣）\nダメだ、涙とまんねぇ……！\n\nでもな、悔いはねぇんだ。全力でやった。\nバレーと同じだよ。トスを上げるやつがいて、アタックが決まる。\n\n{name}、おれのトスだ。……決めてこい！」",
    noa: "「……あー、落ちちゃった。\nでもオレ、ここで過ごした時間、chillで最高だったよ。\n\n{name}、あんまり気負いすぎるなよ。\nSlow and steady、だろ？ ……じゃ、また」",
    roi: "「……ふっ。このロイ様が落ちるとはね。\n世界がまだオレのおしゃれに追いついてなかったな。\n\n{name}、おまえのステージ衣装、いつかオレがデザインしてやる。\n約束な。……泣いてないし。これはラメだし」",
    masaki: "「悔しい、です。すごく。\nでも……努力が足りなかったのは、自分がいちばん分かってる。\n\n{name}くん、君の努力は僕が保証する。\nだから最後まで、胸を張って。……応援してる」",
    shuto: "「……ちぇっ。ここまでかー！\n\nでもさ、おれ、いたずらばっかりだったけど、\nほんとはみんなの笑顔が見たかっただけなんだ。\n\n{name}！ 最後にでっかい笑顔、見せてやれよな！」",
    daigo: "「……あかんかったわ！！（号泣）\n\nなあ、みんな！ おれ、ここに来てよかった！\nこんな本気のやつらと出会えて、最っ高やった！！\n\n{name}！ おまえのこと、弟やと思っとるからな。\n兄ちゃんの分まで……頼んだで！！\n\n（全員で抱き合って、誰よりも大きな声で泣いた）」",
    yuma: "「……負けは負け。言い訳はしない。\n\nでも、ひとつだけ言わせて。\n{name}、おまえと踊った合宿のステージ、\nおれのダンス人生で、一番たのしかった。\n\n……それが、くやしいんだよ。じゃあな」",
    takuto: "「……そっか。ここまでか。\n……ふしぎと、すっきりしてるよ。\nおまえたちの成長を、いちばん近くで見られたから。\n\nなあ、デビューしたら、また回転ずし行こうな。\n今度はおれのおごり。\n……順位より、その約束のほうがずっと大事だ」",
  };
  return t[id] || "「……ここまでだ」";
}
function dropFx(id) {
  const f = { kai: { st: { vo: 5, me: 4 } }, sora: { st: { me: 6 } }, haru: { st: { ex: 5, me: 5 } }, hara: { st: { me: 5, ex: 4 } }, takuto: { st: { me: 6, vo: 4 } }, noa: { st: { me: 4 } }, roi: { st: { ex: 5 } }, masaki: { st: { me: 5, vo: 3 } }, shuto: { st: { ex: 4, da: 3 } } };
  return Object.assign({ msg: `${CANDS[id].n} が去った。想いを受け取った` }, f[id] || {});
}

/* ================= エンディング ================= */
/* ---------- 救済：復活試験（脱落の危機） ---------- */
function revivalExam() {
  showEvent({
    c: "kanade",
    t: "「……待って。\n審査員特権で、一度だけ『復活試験』を出せる。\n使うのは、きみが最後だ。\n\nこの試験に受かれば、オーディションに残れる。\n──見せて。きみの本気」",
    ch: [{ t: "「お願いします」", fx: {}, after: () => startQuiz({
      mode: "aud", lv: 3, total: 8, title: "🌙 復活試験",
      onEnd: r => {
        G.totalQ += r.total; G.totalOK += r.correct; G.bestCombo = Math.max(G.bestCombo, r.best);
        if (r.score >= 50) {
          G.warn = true;   /* 崖っぷちのまま続行 */
          toast("🌙 復活！ オーディションに残った（崖っぷち継続中）");
          confetti(30); sfx.clear(); save();
          return showEvent({ c: "kanade", t: "「……おかえり。\nこれで貸しひとつ、ね。\n\n次は、自分の力で残るんだよ」",
            ch: [{ t: "「はい！」", fx: { st: { me: 5 } }, after: () => afterDay() }] });
        }
        ending("out");
      }
    }) }]
  });
}
/* ---------- 救済：追加合格枠（ファイナル敗退） ---------- */
function extraSlot(board) {
  G.extraTried = true; save();
  showEvent({
    c: "tsukasa",
    t: "「──待て。\n\nデビューメンバーの活動と並行して、\n『追加デビュー枠』を1つ用意することが、たったいま決まった。\n\n条件はひとつ。いまここで、俺たち3人を納得させるパフォーマンスをすること。\n\n最後のステージだ。上がれ」",
    ch: [{ t: "ステージへ", fx: { cond: 1 }, after: () => startQuiz({
      mode: "aud", lv: 4, total: 10, title: "🔥 追加合格チャレンジ",
      onEnd: r => {
        G.totalQ += r.total; G.totalOK += r.correct; G.bestCombo = Math.max(G.bestCombo, r.best);
        if (r.score >= 60) return ending("extra", board);
        if (r.score >= 40) return ending("extraHalf", board);
        ending("final", board);
      }
    }) }]
  });
}

function ending(kind, board) {
  const stTotal = STATS.reduce((s, x) => s + G.st[x.k], 0);
  let rk, title, text;
  if (kind === "extra") {
    rk = "A"; title = "追加合格デビュー！";
    text = `「──合格だ」\n\nフマが、はじめて笑った。\n\n一度は呼ばれなかった名前が、\n最後の最後で、いちばん大きな拍手で呼ばれた。\n\nあきらめなかったやつにしか、\nこのステージは見えない。`;
  } else if (kind === "extraHalf") {
    rk = "B+"; title = "特別練習生デビュー内定！";
    text = `「……完璧じゃない。だが、目は良かった」\n\nショリがそう言って、1枚の紙を差し出した。\n特別練習生契約──半年後のデビューが約束された切符。\n\n遠回りだけど、道はつながった。`;
  } else if (kind === "out") {
    rk = "OUT"; title = "脱落";
    text = `名前は、呼ばれなかった。\n\n控室に戻る足が、やけに重い。\n\nでも30日前の自分より、計算はずっと速くなった。\nそれだけは、誰にも取られない。\n\nまた、来年。`;
  } else if (kind === "time") {
    rk = "C"; title = "審査終了";
    text = `オーディションは終わった。\n結果は、まだ出ていない。`;
  } else {
    const myRank = board.findIndex(b => b.me) + 1;
    const my = board.find(b => b.me);
    if (myRank === 1) { rk = "S"; title = "センターデビュー";
      text = `最初に呼ばれたのは、${G.name}の名前だった。\n\n「タイムレッスーの新しいセンターは、おまえだ」\nフマがそう言った瞬間、\n膝から力が抜けた。\n\n20,000人の頂点。\nその足元にあるのは、\n毎日たたき込んだ、あのくだらないほど地味な計算だった。`; }
    else if (myRank <= 5) { rk = "A"; title = "デビュー決定";
      text = `${myRank}人目に、${G.name}の名前が呼ばれた。\n\nまだセンターじゃない。\nでも、タイムレッスーの新メンバーとして、ステージの上にいる。\n\nここからが、本当のスタートだ。`; }
    else if (my.s >= 70) { rk = "B"; title = "あと一歩";
      text = `呼ばれなかった。\n\nあと数点。\nその数点が、どれだけ遠いか思い知った。\n\n帰り道、ソウが追いかけてきて言った。\n「来年も、待ってるから」`; }
    else { rk = "C"; title = "届かなかった";
      text = `届かなかった。\n\n実力が足りなかった。それだけだ。\n\nでも、悔しさの正体はもうわかっている。\nそれは、次に進むための材料だ。`; }
  }

  const aliveChars = CAND_IDS.filter(id => G.aff[id] > 0);
  const topChar = aliveChars.length ? aliveChars.reduce((a, b) => G.aff[a] >= G.aff[b] ? a : b) : null;
  const bond = topChar && G.aff[topChar] >= 60 ? `<div style="margin-top:12px;display:flex;gap:11px;align-items:center;background:#0e0e16;border-radius:8px;padding:11px;box-shadow:0 0 0 1px var(--line) inset">
    ${pImg(topChar, 54, 64)}<div style="font-size:12px;text-align:left;line-height:1.9">
    <b style="color:${CANDS[topChar].c}">${CANDS[topChar].n} とのエンディング</b><br>${bondEndText(topChar, rk)}</div></div>` : "";

  const point = stTotal / 5 + (board ? board.find(b => b.me).s : 40) + G.auds.filter(a => a.pass).length * 6;
  const dp = Math.round(point / 3 + G.fans / 800 + G.pf.pi + G.pf.frac + G.pf.ratio + G.pf.gyaku + G.pf.kufuu);
  DB.meta.dp += dp; DB.meta.plays++;
  DB.meta.hall.unshift({
    name: G.name, av: G.av, rank: rk, title, fans: G.fans, skills: G.skills.length,
    acc: G.totalQ ? Math.round(G.totalOK / G.totalQ * 100) : 0, st: { ...G.st },
  });
  DB.meta.hall = DB.meta.hall.slice(0, 12);
  DB.run = null; G.done = true; save();
  if (rk === "S" || rk === "A") { confetti(70); sfx.clear(); }

  $("endCard").innerHTML = `
    <div class="lbl">${kind === "out" ? "AUDITION FAILED" : "FINAL RESULT"}</div>
    <div class="endRank" style="${rk === "OUT" ? "background:linear-gradient(180deg,#fff,#e63946 50%,#6a0d18);-webkit-background-clip:text;background-clip:text;font-size:min(18vw,64px)" : rk.length > 1 ? "font-size:min(17vw,72px)" : ""}">${rk}</div>
    <div class="endTitle">${title}</div>
    <div style="display:flex;justify-content:center;margin:6px 0 12px">
      <img src="${AVATARS[G.av].img}" style="width:92px;height:110px;border-radius:6px;object-fit:cover;box-shadow:0 10px 30px #000">
    </div>
    <div class="endText">${text.replace(/\n/g, "<br>")}</div>
    ${bond}
    <div class="endStats">
      ${STATS.map(s => `<div>${s.n} <b>${Math.round(G.st[s.k])}</b> <span style="color:${rank(Math.round(G.st[s.k]))[2]}">${rank(Math.round(G.st[s.k]))[1]}</span></div>`).join("")}
      <div>📈 注目度 <b>${G.fans.toLocaleString()}</b></div>
      <div>✨ スキル <b>${G.skills.length}</b></div>
      <div>✏️ 正答率 <b>${G.totalQ ? Math.round(G.totalOK / G.totalQ * 100) : 0}%</b></div>
      <div>🔥 最大コンボ <b>${G.bestCombo}</b></div>
    </div>
    <div class="dpGet">💠 プロジェクトポイント <b>+${dp}</b><br>
      <span style="font-size:10.5px;color:var(--ink3)">次の挑戦の強化に使える</span></div>
    <button class="btn" id="endOk">タイトルへ</button>`;
  show("scrEnd");
  $("endOk").onclick = () => { sfx.tap(); G = null; renderTitle(); };
}
function bondEndText(id, rk) {
  const t = {
    shion: "「……見てた。ずっと。<br>おまえのステージ、いちばん前で」",
    ren:   "「今回は、おまえの勝ちだ。<br>……次は、ぜったい負けない」",
    haru:  "「うおおお やったな！！<br>……おれの分も、頼んだぞ」",
    kai:   "「よくやった。<br>……おれが行けなかった場所だ。しっかり立ってろ」",
    sora:  "「かっこよかったです！<br>ぼくも、来年ぜったい行きます」",
    takuto: "「約束、覚えてるか？ 回転ずし。<br>……おれのおごりだ。何皿でも食え」",
    hara:  "「ちゃぼすーー！！（号泣）<br>……ダメだ、言葉になんねぇ！！ 最高だよおまえ！！」",
    shino: "「……となり、いい？<br>……ずっと、こうなる気がしてた。……ふふ」",
  };
  return t[id] + (rk === "S" ? `<br><span style="color:var(--gold)">☆ BEST ENDING ☆</span>` : "");
}

/* ================= ショップ ================= */
function openShop() {
  const own = G.ownOutfits;
  openSheet(`<div class="ptitle">衣装 &amp; アイテム<small>📈 注目度 ${G.fans.toLocaleString()} が通貨</small></div>
  <div class="lbl" style="margin:8px 0 6px">STAGE COSTUME（表現力アップ・永続）</div>
  <div class="list">${OUTFITS.map(o => {
    const has = own.includes(o.id);
    return `<div class="item ${!has && G.fans < o.cost ? "lock" : ""}"><span class="ie">${o.e}</span>
      <div class="it"><b>${o.n}</b><small>表現力 +${o.ex}　／　${o.cost.toLocaleString()}</small></div>
      ${has ? (G.outfit === o.id ? `<span class="own">着用中</span>` : `<button class="buy" data-w="${o.id}">着る</button>`)
            : `<button class="buy" data-b="${o.id}" ${G.fans < o.cost ? "disabled" : ""}>買う</button>`}</div>`;
  }).join("")}</div>
  <div class="lbl" style="margin:14px 0 6px">ITEM</div>
  <div class="list">${ITEMS.map(o => `<div class="item ${G.fans < o.cost ? "lock" : ""}"><span class="ie">${o.e}</span>
      <div class="it"><b>${o.n}</b><small>${o.d}　／　${o.cost.toLocaleString()}</small></div>
      <button class="buy" data-i="${o.id}" ${G.fans < o.cost || (o.id === "note" && G.items.note) ? "disabled" : ""}>買う</button></div>`).join("")}</div>
  <div style="height:12px"></div><button class="btn dark" onclick="closeSheet()">閉じる</button>`);
  $("sheetPanel").querySelectorAll(".buy").forEach(b => b.onclick = () => {
    const { b: bid, w: wid, i: iid } = b.dataset;
    if (wid) { G.outfit = wid; sfx.shop(); }
    else if (bid) {
      const o = OUTFITS.find(x => x.id === bid);
      if (G.fans < o.cost) return;
      G.fans -= o.cost; G.ownOutfits.push(o.id); G.outfit = o.id;
      if (!DB.meta.outfits.includes(o.id)) DB.meta.outfits.push(o.id);
      addStat("ex", o.ex); sfx.shop(); toast(`${o.e} ${o.n} を入手　表現力 +${o.ex}`);
    } else if (iid) {
      const o = ITEMS.find(x => x.id === iid);
      if (G.fans < o.cost) return;
      G.fans -= o.cost; sfx.shop();
      if (iid === "drink") { G.stam = Math.min(G.maxStam, G.stam + 45); toast("🥤 体力 +45"); }
      if (iid === "omamori") { G.items.omamori++; toast("🍱 差し入れを入手"); }
      if (iid === "note") { G.items.note = 1; toast("📓 制限時間が伸びた"); }
    }
    save(); openShop(); renderMain(); $("ovSheet").classList.add("on");
  });
}

/* ================= スキル一覧 ================= */
function openSkills() {
  openSheet(`<div class="ptitle">スキル<small>PERFECTを重ねると覚える</small></div>
  <div class="list">${SKILLS.map(s => {
    const has = G.skills.includes(s.id);
    return `<div class="item ${has ? "" : "lock"}"><span class="ie">${s.e}</span>
      <div class="it"><b>${has ? s.n : "？？？"}</b><small>${has ? s.d : condText(s)}</small></div>
      ${has ? `<span class="own">習得</span>` : ""}</div>`;
  }).join("")}</div>
  <div style="height:12px"></div><button class="btn dark" onclick="closeSheet()">閉じる</button>`);
}
function condText(s) {
  const m = {
    pi3: "ボーカル練習で PERFECT 3回", pi8: "ボーカル練習で PERFECT 8回",
    fr3: "ダンス練習で PERFECT 3回", fr8: "ダンス練習で PERFECT 8回",
    ra3: "表現力トレで PERFECT 3回", ra8: "表現力トレで PERFECT 8回",
    gy3: "トーク練習で PERFECT 3回", gy8: "トーク練習で PERFECT 8回",
    ku3: "自主トレで PERFECT 3回", king: "5ジャンルすべてで PERFECT 5回",
    combo: "最大コンボ 15", nomiss: "練習で 100点", iron: "精神力 70以上", star: "好感度の合計 200以上",
    rev5: "リベンジ成功 5回", rev15: "リベンジ成功 15回", rev30: "リベンジ成功 30回",
  };
  return "条件：" + (m[s.id] || "？");
}

/* ================= 記録 ================= */
let zTab = 0;
function openZukan() {
  const tabs = ["デビュー記録", "スキル", "衣装", "データ"];
  let body = "";
  if (zTab === 0) {
    body = DB.meta.hall.length ? `<div class="list">${DB.meta.hall.map(h => `
      <div class="item"><img class="ii" src="${AVATARS[h.av].img}" alt="">
      <div class="it"><b>${esc(h.name)}　<span class="badge" style="color:${h.rank === "OUT" ? "#e63946" : "#ffcf5c"}">${h.rank}</span></b>
      <small>${h.title}　／　注目度 ${h.fans.toLocaleString()}　正答率 ${h.acc}%</small></div></div>`).join("")}</div>`
      : `<div class="smallnote">まだ誰も挑戦を終えていない。</div>`;
  } else if (zTab === 1) {
    body = `<div class="list">${SKILLS.map(s => {
      const has = DB.meta.skills.includes(s.id);
      return `<div class="item ${has ? "" : "lock"}"><span class="ie">${has ? s.e : "？"}</span>
        <div class="it"><b>${has ? s.n : "？？？"}</b><small>${has ? s.d : condText(s)}</small></div></div>`;
    }).join("")}</div><div class="smallnote">${DB.meta.skills.length} / ${SKILLS.length} 種 コンプリート</div>`;
  } else if (zTab === 2) {
    body = `<div class="list">${OUTFITS.map(o => {
      const has = DB.meta.outfits.includes(o.id);
      return `<div class="item ${has ? "" : "lock"}"><span class="ie">${has ? o.e : "？"}</span>
        <div class="it"><b>${has ? o.n : "？？？"}</b><small>表現力 +${o.ex}</small></div></div>`;
    }).join("")}</div>`;
  } else {
    const keys = Object.keys(DB.meta.best);
    body = keys.length ? `<div class="list">${keys.sort().map(k => {
      const [g, lv] = k.split("_"), b = DB.meta.best[k];
      return `<div class="item"><span class="ie">🔥</span><div class="it"><b>${MATH.GENRE_NAME[g]}　Lv.${lv}</b>
        <small>ベストタイム ${b.time}秒　／　正解 ${b.ok}/20</small></div></div>`;
    }).join("")}</div>` : `<div class="smallnote">特訓モードの記録がここに残る。</div>`;
    body += `<div class="divider"></div>
      <div class="kv"><span>挑戦した回数</span><b>${DB.meta.plays}</b></div>
      <div class="kv"><span>見たイベント</span><b>${DB.meta.evseen.length} / ${EVENTS.length}</b></div>
      <div class="kv"><span>プロジェクトポイント</span><b>${DB.meta.dp}</b></div>`;
  }
  openSheet(`<div class="ptitle">記録</div>
    <div class="tabs">${tabs.map((t, i) => `<button class="tab ${i === zTab ? "on" : ""}" data-t="${i}">${t}</button>`).join("")}</div>
    ${body}<div style="height:12px"></div><button class="btn dark" onclick="closeSheet()">閉じる</button>`);
  $("sheetPanel").querySelectorAll(".tab").forEach(b => b.onclick = () => { zTab = +b.dataset.t; sfx.tap(); openZukan(); });
}

/* ================= 強化（引きつぎ） ================= */
const UPS = [
  { k: "st",   n: "初期ステータス", e: "📈", d: "はじめのステータス +5", cost: 20, max: 5 },
  { k: "stam", n: "体力の最大値",   e: "💪", d: "体力の最大 +10",       cost: 15, max: 5 },
  { k: "eff",  n: "練習効率",       e: "⚡️", d: "練習の伸び +10%",      cost: 30, max: 5 },
  { k: "fan",  n: "初期注目度",     e: "📣", d: "はじめの注目度 +500",  cost: 10, max: 5 },
  { k: "aff",  n: "初期好感度",     e: "🤝", d: "全員の好感度 +10",     cost: 12, max: 5 },
];
function openDream() {
  openSheet(`<div class="ptitle">強化メニュー<small>挑戦を終えるともらえるポイントで、次を強くする</small></div>
  <div style="text-align:center;font-size:13px;margin-bottom:12px">所持 💠 <b style="font-size:24px;color:var(--gold)">${DB.meta.dp}</b></div>
  <div class="list">${UPS.map(u => {
    const lv = DB.meta.up[u.k], full = lv >= u.max, cost = u.cost * (lv + 1);
    return `<div class="item ${DB.meta.dp < cost && !full ? "lock" : ""}"><span class="ie">${u.e}</span>
      <div class="it"><b>${u.n} <span class="badge">Lv.${lv}/${u.max}</span></b><small>${u.d}${full ? "" : `　／ 💠${cost}`}</small></div>
      ${full ? `<span class="own">MAX</span>` : `<button class="buy" data-u="${u.k}" ${DB.meta.dp < cost ? "disabled" : ""}>強化</button>`}</div>`;
  }).join("")}</div>
  <div style="height:12px"></div><button class="btn dark" onclick="closeSheet()">閉じる</button>`);
  $("sheetPanel").querySelectorAll(".buy").forEach(b => b.onclick = () => {
    const u = UPS.find(x => x.k === b.dataset.u);
    const cost = u.cost * (DB.meta.up[u.k] + 1);
    if (DB.meta.dp < cost) return;
    DB.meta.dp -= cost; DB.meta.up[u.k]++;
    sfx.shop(); save(); openDream(); renderTitle(); $("ovSheet").classList.add("on");
  });
}

/* ================= 特訓 ================= */
let drill = { g: "pi", lv: 1 };
function openDrill() {
  const gs = Object.keys(MATH.GENRE_NAME);
  openSheet(`<div class="ptitle">特訓モード<small>20問タイムアタック</small></div>
    <div class="lbl" style="margin:4px 0 6px">GENRE</div>
    <div class="list">${gs.map(g => `<button class="item" data-g="${g}" style="${g === drill.g ? "box-shadow:0 0 0 1.5px var(--gold) inset" : ""}">
      <span class="ie">${{ pi: "🥧", frac: "🍰", ratio: "⚖️", gyaku: "🔙", kufuu: "💡", bun: "📖" }[g]}</span>
      <div class="it"><b>${MATH.GENRE_NAME[g]}</b><small>${bestText(g, drill.lv)}</small></div></button>`).join("")}</div>
    <div class="lbl" style="margin:14px 0 6px">LEVEL</div>
    <div class="tabs">${[1, 2, 3, 4, 5].map(l => `<button class="tab ${l === drill.lv ? "on" : ""}" data-l="${l}">Lv.${l}</button>`).join("")}</div>
    <button class="btn" id="drillGo">スタート</button>
    <div style="height:8px"></div><button class="btn dark" onclick="closeSheet()">閉じる</button>`);
  $("sheetPanel").querySelectorAll("[data-g]").forEach(b => b.onclick = () => { drill.g = b.dataset.g; sfx.tap(); openDrill(); });
  $("sheetPanel").querySelectorAll("[data-l]").forEach(b => b.onclick = () => { drill.lv = +b.dataset.l; sfx.tap(); openDrill(); });
  $("drillGo").onclick = () => {
    closeSheet(); sfx.tap();
    startQuiz({ mode: "drill", genre: drill.g, lv: drill.lv, total: 20,
      title: `🔥 ${MATH.GENRE_NAME[drill.g]} Lv.${drill.lv}`, onEnd: r => finishDrill(r) });
  };
}
function bestText(g, lv) {
  const b = DB.meta.best[`${g}_${lv}`];
  return b ? `Lv.${lv} ベスト ${b.time}秒（正解 ${b.ok}/20）` : `Lv.${lv} 記録なし`;
}
function finishDrill(r) {
  const key = `${drill.g}_${drill.lv}`;
  const old = DB.meta.best[key];
  const isBest = r.correct >= 18 && (!old || r.totalTime < old.time);
  if (isBest) { DB.meta.best[key] = { time: r.totalTime, ok: r.correct }; save(); confetti(24); }
  const miss = r.misses.slice(0, 8).map(m => `<div class="missRow"><span>${m.q}</span><em>${MATH.ansHtml(m.a)}</em></div>`).join("");
  $("resPanel").innerHTML = `
    <div class="resHead">
      <div class="lbl">${MATH.GENRE_NAME[drill.g]} Lv.${drill.lv}</div>
      <div class="resScore">${r.totalTime}<small> 秒</small></div>
      <div class="resRank" style="background:${isBest ? "#ffcf5c" : "#4cc9f0"}">${isBest ? "ベスト記録更新" : "記録"}</div>
      <div style="font-size:10.5px;color:var(--ink3);margin-top:8px">正解 ${r.correct}/20　1問平均 ${r.avgTime}秒　最大コンボ ${r.best}</div>
      ${old ? `<div style="font-size:10.5px;color:var(--ink3)">これまでのベスト ${old.time}秒</div>` : ""}
      ${r.correct < 18 ? `<div style="font-size:10.5px;color:var(--red);margin-top:4px">※ 18問以上の正解でベスト記録になる</div>` : ""}
    </div>
    ${miss ? `<div class="missBox"><div class="mt">MISSED</div>${miss}</div>` : `<div class="smallnote">全問正解。</div>`}
    ${r.misses.length ? `<button class="btn gold" id="revBtn" style="margin-bottom:8px">📖 復習タイム（解説→リベンジ）</button>` : ""}
    <button class="btn" id="resOk">もどる</button>`;
  $("ovResult").classList.add("on");
  const rb = $("revBtn");
  if (rb) rb.onclick = () => { sfx.tap(); $("ovResult").classList.remove("on"); startRevenge(r.misses, () => { renderTitle(); openDrill(); }); };
  $("resOk").onclick = () => { sfx.tap(); $("ovResult").classList.remove("on"); renderTitle(); openDrill(); };
}

/* ================= 起動 ================= */
window.closeSheet = closeSheet;
renderTitle();
